window.AUTH=window.AUTH||{};window.AUTH["17-587"]={"d":"17-587","id":"2018/17-587","n":"Mount Lemmon Fire District v. Guido","briefs":[{"k":"petitioner","label":"Brief of petitioner Mount Lemmon Fire District","date":"2018-05-07","url":"https://www.supremecourt.gov/DocketPDF/17/17-587/45934/20180507161926219_Merits%20Brief%20for%20E-Filing.pdf","side":"pet","n":71},{"k":"respondent","label":"Brief of respondents John Guido, et al.","date":"2018-07-05","url":"https://www.supremecourt.gov/DocketPDF/17/17-587/52322/20180705140458845_Brief%20of%20Respondents%2017-587.pdf","side":"res","n":122},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2018-07-12","url":"https://www.supremecourt.gov/DocketPDF/17/17-587/54113/20180712160842691_17-587bsacUnitedStates.pdf","side":"us","n":92},{"k":"reply","label":"Reply of petitioner Mount Lemmon Fire District","date":"2018-08-06","url":"https://www.supremecourt.gov/DocketPDF/17/17-587/58582/20180806161227322_Mount%20Lemmon%20Merits%20Reply.pdf","side":"pet","n":25}],"opinion":"https://www.supremecourt.gov/opinions/18pdf/17-587_n7ip.pdf","tr":true,"items":[{"t":"case","label":"Ali v. Fed. Bureau of Prisons","cite":"552 U.S. 214","y":2008,"id":"2007/06-9130","sc":1,"sum":"The Court agreed with the 11th Circuit and, in a 5-4 majority opinion written by Justice Clarence Thomas, held that the use of the word \"any\" should be given its normal interpretation, encompassing all federal officers whether or not they were involved in enforcing customs or excise laws.","sumSrc":"Oyez","by":{"0":"21","2":"17","3":"6, 8"}},{"t":"case","label":"Almond v. Unified Sch. Dist. No. 501","cite":"665 F.3d 1174","y":2011,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/665/1174/","by":{"0":"24"}},{"t":"case","label":"Arbaugh v. Y & H Corp.","cite":"546 U.S. 500","y":2006,"id":"2005/04-944","sc":1,"sum":"The Court held that the number-of-employees requirement is an element of the merits of a Title VII claim, not a jurisdictional limitation.","sumSrc":"Oyez","by":{"0":"4"}},{"t":"case","label":"Bd. of Trs. of Univ. of Ala. v. Garrett","cite":"531 U.S. 356","y":2001,"id":"2000/99-1240","sc":1,"sum":"The Court held that suits in federal court by state employees to recover money damages by reason of the state's failure to comply with Title I of the ADA are barred by the Eleventh Amendment.","sumSrc":"Oyez","by":{"0":"57"}},{"t":"case","label":"Birkbeck v. Marvel Lighting Corp.","cite":"30 F.3d 507","y":1994,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/30/507/","by":{"0":"29, 30","2":"20"}},{"t":"case","label":"Bloate v. United States","cite":"559 U.S. 196","y":2010,"id":"2009/08-728","sc":1,"sum":"The Court held that the time granted to prepare pretrial motions is not automatically granted exclusion from the Speedy Trial Act's 70-day time limit.","sumSrc":"Oyez","by":{"0":"33"}},{"t":"case","label":"Bond v. United States","cite":"134 S. Ct. 2077","y":2014,"id":"2013/12-158","sc":1,"sum":"The Court found that international treaties cannot overstep state sovereignty, and enforcement should be limited to international affairs.","sumSrc":"Oyez","by":{"0":"37","3":"17"}},{"t":"case","label":"Busby v. City of Orlando","cite":"931 F.2d 764","y":1991,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/931/764/","by":{"0":"30"}},{"t":"case","label":"Butler v. City of Prairie Vill.","cite":"172 F.3d 736","y":1999,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/172/736/","by":{"0":"31"}},{"t":"case","label":"Cal. Pub. Emps.’ Ret. Sys. v. ANZ Secs., Inc.","cite":"137 S. Ct. 2042","y":2017,"id":"2016/16-373","sc":1,"sum":"The Court determined that the filing of a putative class action lawsuit does not satisfy the three-year time limit in Section 13 of the Securities Act with respect to the individual claims of other class members.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"Chattanooga Foundry & Pipe Works v. City of Atl.","cite":"203 U.S. 390","y":1906,"id":"scdb/1906-040","sc":1,"ar":2,"sum":"By express provision of the act of July 2, 1890, 26 Stat. 209, a city is a person within the meaning of section 7 of that act, and can maintain an action against a party to a combination unlawful under the act by reason of which it has been forced to pay a price for an article above what rt is reasonably worth.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"Church of the Lukumi Babalu Aye v. City of Hialeah","cite":"508 U.S. 520","y":1993,"id":"1992/91-948","sc":1,"sum":"The Court found that an ordinance banning religious animal sacrifice was unconstitutional under the Free Exercise Clause of the First Amendment.","sumSrc":"Oyez","by":{"0":"48"}},{"t":"case","label":"Cink v. Grant Cty.","cite":"635 F. App’x 470","y":2015,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/635/470/","by":{"0":"9, 25"}},{"t":"case","label":"City of Cleburne v. Cleburne Living Ctr.","cite":"473 U.S. 432","y":1985,"id":"1984/84-468","sc":1,"sum":"In a unanimous judgment, the Court held that the denial of the special use permit to Cleburne Living Centers, Inc. was premised on an irrational prejudice against the mentally retarded, and hence unconstitutional under the Equal Protection Clause of the Fourteenth Amendment.","sumSrc":"Oyez","by":{"0":"48"}},{"t":"case","label":"City of Lafayette v. La. Power & Light Co.","cite":"435 U.S. 389","y":1978,"id":"1977/76-864","sc":1,"ar":1,"sum":"Apart from whether petitioners are exempt from the antitrust laws as agents of the State under the Parker doctrine there are insufficient grounds for inferring that Congress did not intend to subject cities to antitrust liability.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20, 22"}},{"t":"case","label":"City of Lincoln v. Ricketts","cite":"297 U.S. 373","y":1936,"id":"scdb/1935-056","sc":1,"sum":"that a municipality is a \"corporation\" and hence a \"person\" within the meaning of this provision if entitled to priority by the law of its State. Pp. 374, 377. 77 F. (2d) 425, reversed. CERTIORARI, 296 U. S. 566, to review a judgment denying the City's claim of preference in a bankruptcy case. Mr. Don W. Stewart, with whom Mr. Karl W. Kindleberger was on the brief, for petitioners. Mr. R. A. Boehmer, with whom Mr. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20, 22, 23"}},{"t":"case","label":"Clark v. Martinez","cite":"543 U.S. 371","y":2005,"id":"2004/03-878","sc":1,"sum":"The Court said the requirement that immigrants be detained no longer than reasonably necessary for deportation applied to both admissible and inadmissible immigrants. Because readmission to Cuba was unforeseeable, the detentions of Martinez and Benitez were unreasonable.","sumSrc":"Oyez","by":{"0":"32, 41"}},{"t":"case","label":"Clinton v. City of New York","cite":"524 U.S. 417","y":1998,"id":"1997/97-1374","sc":1,"sum":"A case in which the Court declared that pieces of legislation passed by both houses of Congress must be either passed or vetoed as a whole, not in separate parts.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Cmty. Commc’ns Co. v. City of Boulder","cite":"455 U.S. 40","y":1982,"id":"1981/80-1350","sc":1,"sum":"Boulder's moratorium ordinance is not exempt from antitrust scrutiny under the Parkerdoctrine.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20"}},{"t":"case","label":"Cook Cty. v. United States ex rel. Chandler","cite":"538 U.S. 119","y":2003,"id":"2002/01-1572","sc":1,"sum":"The Court held that the term \"person\" includes local governments. The Court noted that the County, as a recipient of federal funding, was clearly able to abuse federal spending and was thus subject to the FCA remedy that applied to prevent such abuse.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Corr v. MTA Long Island Bus","cite":"199 F.3d 1321","y":1999,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/199/1321/","by":{"0":"31"}},{"t":"case","label":"Dici v. Pennsylvania","cite":"91 F.3d 542","y":1996,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/91/542/","by":{"0":"30"}},{"t":"case","label":"EEOC v. AIC Sec. Investigations, Ltd.","cite":"55 F.3d 1276","y":1995,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/55/1276/","by":{"0":"31"}},{"t":"case","label":"EEOC v. Bd. of Supervisors for Univ. of La. Sys.","cite":"559 F.3d 270","y":2009,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/559/270/","by":{"0":"57","2":"27"}},{"t":"case","label":"EEOC v. Monclova Twp.","cite":"920 F.2d 360","y":1990,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/920/360/","op":1,"sum":"Noting the EEOC’s position that the text of Section 630(b) “unambiguously excludes [political subdivisions] from the minimum number of employees requirement” and that “no reason exists to avoid [Section 630(b)’s] statutory language”.","sumSrc":"brief:1","by":{"0":"9, 10","1":"2","2":"4"}},{"t":"case","label":"EEOC v. Walker Cty. Bd. of Educ.","cite":"2012 WL 13020711","y":2012,"court":"N.D. Ala. Jan. 30","by":{"0":"38"}},{"t":"case","label":"EEOC v. Wyoming","cite":"460 U.S. 226","y":1983,"id":"1982/81-554","sc":1,"op":1,"sum":"The extension of the Age Discrimination in Employment Act to cover state and local governments is a valid exercise of Congress' powers under the Commerce Clause, both on its face and as applied in this case, and is not precluded by virtue of external constraints imposed on Congress' commerce powers by the Tenth Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"9, 41, 49","1":"passim","2":"7, 11, 26, 28","3":"10, 18"}},{"t":"case","label":"Encino Motorcars, LLC v. Navarro","cite":"138 S. Ct. 1134","y":2018,"id":"2017/16-1362","sc":1,"sum":"The Court decided that because service advisors at car dealerships are “salesm[e]n . . . primarily engaged in . . . servicing automobiles,” 29 U.S.C. § 213(b)(10)(A), they are exempt from the Fair Labor Standards Act's overtime-pay requirements.","sumSrc":"Oyez","by":{"0":"34"}},{"t":"case","label":"Fantini v. Salem State Coll.","cite":"557 F.3d 22","y":2009,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/557/22/","by":{"0":"30"}},{"t":"case","label":"Gary v. Long","cite":"59 F.3d 1391","y":1995,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/59/1391/","op":1,"by":{"0":"30"}},{"t":"case","label":"Gebser v. Lago Vista Ind. Sch. Dist.","cite":"524 U.S. 274","y":1998,"id":"1997/96-1866","sc":1,"ar":1,"sum":"In a 5-to-4 decision the Court held that two minimal criteria must be met in order for an aggrieved party to recover sexual harassment damages under the Amendments. First, the party must show that a school district official, with the ability to institute corrective measures, knew of the forbidden conduct.","sumSrc":"Oyez","by":{"0":"31","1":"35"}},{"t":"case","label":"Gregory v. Ashcroft","cite":"501 U.S. 452","y":1991,"id":"1990/90-50","sc":1,"sum":"In addition to emphasizing Missouri's, or any other state's, Tenth Amendment right to define the qualifications of its highest state officials, the Court held that the regulations of the ADEA did not apply to \"policy-making\" appointees such as state court judges.","sumSrc":"Oyez","by":{"0":"9, 15, 37, 39, 40, 41","1":"36, 37","2":"7, 25, 26","3":"17"}},{"t":"case","label":"Harvey v. Blake","cite":"913 F.2d 226","y":1990,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/913/226/","by":{"0":"30, 57","2":"20"}},{"t":"case","label":"Haynes v. Williams","cite":"88 F.3d 898","y":1996,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/88/898/","by":{"0":"30"}},{"t":"case","label":"Hiler v. Brown","cite":"177 F.3d 542","y":1999,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/177/542/","by":{"0":"30"}},{"t":"case","label":"Hunt v. District of Columbia","cite":"2002 WL 1997987","y":2002,"court":"D.C. Cir. Aug. 29","by":{"0":"31"}},{"t":"case","label":"Kelly v. Wauconda Park Dist.","cite":"801 F.2d 269","y":1986,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/801/269/","op":1,"sum":"Noting that no congressional report “drew any distinction between the coverage of public and private employers”.","sumSrc":"brief:0","by":{"0":"9, 10, 25, 45, 46, 49","1":"2, 5, 23, 25","2":"4, 5"}},{"t":"case","label":"Kimel v. Fla. Bd. of Regents","cite":"528 U.S. 62","y":2000,"id":"1999/98-791","sc":1,"sum":"The Court held that the ADEA contains a clear statement of Congress' intent to abrogate the states' immunity, but that the abrogation exceeds Congress' authority under the Fourteenth Amendment. \"States may discriminate on the basis of age without offending the Fourteenth Amendment if the age classification in question is rationally related to a legitimate state interest,\" wrote Justice O'Connor for the Court.","sumSrc":"Oyez","by":{"0":"48, 56","1":"28, 30, 39","2":"22, 27, 32"}},{"t":"case","label":"Koons Buick Pontiac GMC, Inc. v. Nigh","cite":"543 U.S. 50","y":2004,"id":"2004/03-377","sc":1,"sum":"In an 8-1 judgment delivered by Justice Ruth Bader Ginsburg, the Court held that a 1995 TILA amendment did not change the original limit on violations involving personal-property loans. Congress intended the amendment to raise the minimum and maximum recoveries for closed-end loans secured by real property. Congress had not sought to remove the $1,000 cap on loans secured by personal property.","sumSrc":"Oyez","by":{"0":"18, 44","3":"19"}},{"t":"case","label":"Koslow v. Pennsylvania","cite":"302 F.3d 161","y":2002,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/302/161/","by":{"0":"31"}},{"t":"case","label":"Lissau v. S. Food Serv., Inc.","cite":"159 F.3d 177","y":1998,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/159/177/","by":{"0":"30"}},{"t":"case","label":"Lorillard v. Pons","cite":"434 U.S. 575","y":1978,"id":"1977/76-1346","sc":1,"ar":1,"sum":"Yes. Although the ADEA does not expressly provide for jury trials, its structure shows that Congress intended a jury to be available in private ADEA actions when a party seeks one. The Court therefore did not reach the Seventh Amendment question.","sumSrc":"AI-generated brief","by":{"0":"44","1":"1, 27","2":"13, 21"}},{"t":"case","label":"Martin v. Chem. Bank","cite":"129 F.3d 114","y":1997,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/129/114/","by":{"0":"29","3":"13"}},{"t":"case","label":"Mason v. Stallings","cite":"82 F.3d 1007","y":1996,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/82/1007/","by":{"0":"31"}},{"t":"case","label":"McKennon v. Nashville Banner Publ’g Co.","cite":"513 U.S. 352","y":1995,"id":"1994/93-1543","sc":1,"sum":"Alleging that her discharge by respondent Nashville Banner Publishing Company violated the Age Discrimination in Employment Act of 1967 (ADEA), petitioner McKennon filed suit seeking a variety of legal and equitable remedies available under the ADEA, including backpay. After she admitted in her deposition that she had copied several of the Banner's confidential documents during her final year of employment, the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"44","1":"26","2":"21","3":"21"}},{"t":"case","label":"McNally v. United States","cite":"483 U.S. 350","y":1987,"id":"1986/86-234","sc":1,"sum":"The jury charge permitted a conviction for conduct not within the reach of § 1341.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"33, 34"}},{"t":"case","label":"Meekison v. Voinovich","cite":"67 F. App’x 900","y":2003,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/67/900/","by":{"0":"57"}},{"t":"case","label":"Miller v. Maxwell’s Int’l Inc.","cite":"991 F.2d 583","y":1993,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/991/583/","by":{"0":"29, 30, 54, 57","3":"13"}},{"t":"case","label":"Monell v. Dep’t of Soc. Servs. of City of New York","cite":"436 U.S. 658","y":1978,"id":"1977/75-1914","sc":1,"ar":1,"sum":"The Court held that the legislative history of the Civil Rights Act of 1871, and specifically the Sherman Amendment, indicated that municipalities could be liable for the infringement of constitutional rights. Additionally, by 1871 there was a clear legislative and precedent-based history for municipal corporations — such as a school board — to be considered a “person” for the purpose of lawsuits and liability.","sumSrc":"Oyez","by":{"0":"20, 31","1":"18, 30"}},{"t":"case","label":"Nev. Dep’t of Human Res. v. Hibbs","cite":"538 U.S. 721","y":2004,"id":"2002/01-1368","sc":1,"sum":"The Court held that State employees may recover money damages in federal court in the event of the State's failure to comply with the FMLA's family-care provision.","sumSrc":"Oyez","by":{"0":"48"}},{"t":"case","label":"NLRB v. Catholic Bishop of Chi.","cite":"440 U.S. 490","y":1979,"id":"1978/77-752","sc":1,"sum":"Schools operated by a church to teach both religious and secular subjects are not within the jurisdiction granted by the National Labor Relations Act, and the NLRB was therefore without authority to issue the orders against respondents.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"41"}},{"t":"case","label":"Northwest, Inc. v. Ginsberg","cite":"134 S. Ct. 1422","y":2014,"id":"2013/12-462","sc":1,"sum":"The Court held that the Airline Deregulation Act preempts claims arising from a frequent flier complaint based on price, route, or air carrier service.","sumSrc":"Oyez","by":{"0":"23"}},{"t":"case","label":"O’Regan v. Arbitration Forums, Inc.","cite":"121 F.3d 1060","y":1997,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/121/1060/","by":{"0":"29"}},{"t":"case","label":"Palmer v. Ark. Council on Econ. Educ.","cite":"154 F.3d 892","y":1998,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/154/892/","op":1,"by":{"0":"9, 10","2":"4"}},{"t":"case","label":"Papa v. Katy Indus., Inc.","cite":"166 F.3d 937","y":1999,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/166/937/","by":{"0":"17, 54"}},{"t":"case","label":"Ratzlaf v. United States","cite":"510 U.S. 135","y":1994,"id":"1993/92-1196","sc":1,"sum":"To give effect to § 5322(a)'s \"willfulness\" requirement, the Government must prove that the defendant acted with knowledge that the structuring he or she undertook was unlawful, not simply that the defendant's purpose was to circumvent a bank's reporting obligation. Section 5324 itself forbids structuring with a \"purpose of evading the [§ 5313(a)] reporting requirements,\" and the lower courts erred in treating the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"32"}},{"t":"case","label":"Roberts v. Sea-Land Servs., Inc.","cite":"566 U.S. 93","y":2012,"id":"2011/10-1399","sc":1,"sum":"The Court held that the Longshore Act sets the period when an injured worker is awarded disability compensation as the fiscal year when the worker first becomes entitled to compensation.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"Roman-Oliveras v. Puerto Rico Elec. Power Auth.","cite":"655 F.3d 43","y":2011,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/655/43/","by":{"0":"30"}},{"t":"case","label":"Sabouri v. Ohio Dep’t of Educ.","cite":"142 F.3d 436","y":1998,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/142/436/","by":{"0":"29"}},{"t":"case","label":"Smith v. Lomax","cite":"45 F.3d 402","y":1995,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/45/402/","by":{"0":"29","3":"13"}},{"t":"case","label":"Smith v. St. Bernards Reg’l Med. Ctr.","cite":"19 F.3d 1254","y":1994,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/19/1254/","by":{"0":"30"}},{"t":"case","label":"State Police for Automatic Ret. Ass’n v. DiFava","cite":"317 F.3d 6","y":2003,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/317/6/","by":{"0":"57"}},{"t":"case","label":"Stults v. Conoco, Inc.","cite":"76 F.3d 651","y":1996,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/76/651/","by":{"0":"29"}},{"t":"case","label":"Sturgeon v. Frost","cite":"136 S. Ct. 1061","y":2016,"id":"2015/14-1209","sc":1,"sum":"The Court held that the Alaska National Interest Lands Conservation Act of 1980 did not allow the National Park Service to regulate all land physically within the boundaries of the National Park System in Alaska.","sumSrc":"Oyez","by":{"0":"5, 13, 17, 18","3":"2, 17"}},{"t":"case","label":"Tomka v. Seiler Corp.","cite":"66 F.3d 1295","y":1995,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/66/1295/","by":{"0":"30"}},{"t":"case","label":"TRW Inc. v. Andrews","cite":"534 U.S. 19","y":2001,"id":"2001/00-1045","sc":1,"sum":"The Court held that a discovery rule does not govern section 1681p of FCRA, as that section explicitly delineated the exceptional case in which discovery triggered the two-year limitation and Adelaide's case does not fall within the exceptional category. The Court reasoned that it was not at liberty to make Congress' explicit exception the general rule.","sumSrc":"Oyez","by":{"0":"22, 23"}},{"t":"case","label":"United States v. Morrison","cite":"529 U.S. 598","y":2000,"id":"1999/99-5","sc":1,"sum":"The Court found that sections of the Violence Against Women Act were unconstitutional under the Commerce Clause.","sumSrc":"Oyez","by":{"0":"43","1":"37"}},{"t":"case","label":"Walsh v. Nev. Dep’t of Human Res.","cite":"471 F.3d 1033","y":2006,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/471/1033/","by":{"0":"30"}},{"t":"case","label":"Williams v. Banning","cite":"72 F.3d 552","y":1995,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/72/552/","by":{"0":"30"}},{"t":"case","label":"Willis v. Dean Witter Reynolds, Inc.","cite":"948 F.2d 305","y":1991,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/948/305/","by":{"0":"42"}},{"t":"case","label":"Yates v. United States","cite":"135 S. Ct. 1074","y":2015,"id":"2014/13-7451","sc":1,"sum":"The Court ruled that a “tangible item” as defined by Section 1519 of the Sarbanes-Oxley Act is one used to record or preserve information.","sumSrc":"Oyez","by":{"0":"18, 21, 33","3":"16"}},{"t":"case","label":"Alaska Dep’t of Envtl. Conservation v. EPA","cite":"540 U.S. 461","y":2004,"id":"2003/02-658","sc":1,"sum":"The Court held that the Clean Air Act authorized the EPA to bar the construction of the polluting facility in Alaska. Though Alaska determined the facility's use of \"Low NOx\" met the act's requirement that facilities use \"best available control technology,\" the EPA was reasonable to reject this claim.","sumSrc":"Oyez","by":{"1":"25"}},{"t":"case","label":"Astoria Fed. Sav. & Loan Ass’n v. Solimino","cite":"501 U.S. 104","y":1991,"id":"1990/89-1895","sc":1,"sum":"Judicially unreviewed state administrative findings have no preclusive effect on age-discrimination proceedings in federal court. While well-established common-law principles, such as preclusion rules, are presumed to apply in the absence of a legislative intent to the contrary, Congress need not state expressly its intention to overcome a presumption of administrative estoppel. Clear-statement requirements are …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"34"}},{"t":"case","label":"Ball v. Renner","cite":"54 F.3d 664","y":1995,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/54/664/","by":{"1":"34"}},{"t":"case","label":"Balt. & Potomac R.R. Co. v. Fifth Baptist Church","cite":"108 U.S. 317","y":1883,"id":"scdb/1882-217","sc":1,"sum":"Corporation — ^Damages—Legislative Grant — Nuisance.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"34"}},{"t":"case","label":"Bennett v. Hardy","cite":"784 P.2d 1258","y":1990,"court":"Wash.","url":"https://www.courtlistener.com/c/P.2d/784/1258/","by":{"1":"29"}},{"t":"case","label":"Bragdon v. Abbott","cite":"524 U.S. 624","y":1998,"id":"1997/97-156","sc":1,"sum":"In a 5-to-4 opinion, the Court held that although the ADA does not force care-givers to treat an \"individual [who] poses a direct threat to the health or safety of others,\" it also prohibits discrimination against any individual \"on the basis of disability in the enjoyment of the services of any place of public accommodation by any person who operates [such] a place.\" The Court then reasoned that since HIV \"substantially limits\" major life activities, such as reproduction, the infection is a \"disability\" that entitles its victims to ADA protections.","sumSrc":"Oyez","by":{"1":"24"}},{"t":"case","label":"Burnett v. Grattan","cite":"468 U.S. 42","y":1984,"id":"1983/83-264","sc":1,"sum":"While federal courts properly turn to state law for statutes of limitations in actions under the Civil Rights Acts, borrowing the limitations period from an administrative employment discrimination statute was inappropriate. Both the practical differences between litigation and an administrative proceeding and the divergence in the objectives of the federal causes of action and the state administrative procedure …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"30"}},{"t":"case","label":"Carr v. United States","cite":"560 U.S. 438","y":2010,"id":"2009/08-1301","sc":1,"sum":"The Court held that the Sex Offender and Registration Act does not apply to sex offenders' interstate travel that occurred before the Act's effective date.","sumSrc":"Oyez","by":{"1":"38"}},{"t":"case","label":"Case v. Bowles","cite":"327 U.S. 92","y":1946,"id":"scdb/1945-053","sc":1,"ar":1,"sum":"1. The Emergency Price Control Act applies to the sale by the State of Washington of timber growing on lands granted by Congress to the State \"for the support of common schools,\" notwithstanding a provision in the Enabling Act providing that these lands shall \"be disposed of only at public sale, and at a price not less than\" $10 per acre and a provision of the state constitution that these lands shall not be sold …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"21"}},{"t":"case","label":"Cink v. Grant County","cite":"635 Fed. Appx. 470","y":2015,"court":"10th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./635/470/","op":1,"by":{"1":"39, 40","2":"4, 33"}},{"t":"case","label":"City of Edmonds v. Oxford House, Inc.","cite":"514 U.S. 725","y":1995,"id":"1994/94-23","sc":1,"sum":"The Court held that Edmonds' zoning code definition of the term \"family\" is not a maximum occupancy restriction exempt from the FHA.","sumSrc":"Oyez","by":{"1":"36"}},{"t":"case","label":"City of L.A. Dep’t of Water & Power v. Manhart","cite":"435 U.S. 702","y":1978,"id":"1977/76-1810","sc":1,"sum":"The Court held that the company’s policy was based on aggregate numbers that are not necessarily true for individuals, which violates the Civil Rights Act prohibition of individual discrimination based purely on gender.","sumSrc":"Oyez","by":{"1":"32, 36","2":"19","3":"13, 15"}},{"t":"case","label":"Clifford F. MacEvoy Co. v. United States ex rel. Calvin Tomkins Co.","cite":"322 U.S. 102","y":1944,"id":"scdb/1943-048","sc":1,"sum":"1. Where A sold materials to B who merely sold them to a contractor for use on a Government project, A is not entitled to recover upon a payment bond furnished by the contractor pursuant to the Miller Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"17"}},{"t":"case","label":"D. Ginsberg & Sons, Inc. v. Popkin","cite":"285 U.S. 204","y":1932,"id":"scdb/1931-109","sc":1,"sum":"A court of bankruptcy has no authority under § 2 (15) of the Bankruptcy Act or § 261 of the Judicial Code to issue a writ of ne exeat against an absconding officer of a bankrupt corporation to the end that he may be examined in the bankruptcy proceedings. P. 206. 50 F. (2d) 693, affirmed. CERTIORARI, 284 U. S. 609, to review the reversal of an order sustaining the issuance of a writ of ne exeat in bankruptcy …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"17"}},{"t":"case","label":"Donovan v. Sabine Irrigation Co.","cite":"695 F.2d 190","y":1983,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/695/190/","by":{"1":"33"}},{"t":"case","label":"EEOC v. Arabian Am. Oil Co.","cite":"499 U.S. 244","y":1991,"id":"1990/89-1838","sc":1,"sum":"Title VII does not apply extraterritorially to regulate the employment practices of United States firms that employ American citizens abroad. Petitioners' evidence, while not totally lacking in probative value, falls short of demonstrating the clearly expressed affirmative congressional intent that is required to overcome the well-established presumption against statutory extraterritoriality.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"22, 30"}},{"t":"case","label":"Fed. Express Corp. v. Holowecki","cite":"552 U.S. 389","y":2008,"id":"2007/06-1322","sc":1,"sum":"The Court, in a 7-2 opinion, upheld the Second Circuit, stating that the procedure used to file the document was consistent with the design and purpose of the ADEA.","sumSrc":"Oyez","by":{"1":"24, 25, 26","2":"21, 30"}},{"t":"case","label":"Garcia v. San Antonio Metro. Transit Auth.","cite":"469 U.S. 528","y":1985,"id":"1983/82-1913","sc":1,"sum":"The Court ruled that Congress has the power under the Commerce Clause of the Constitution to extend the Fair Labor Standards Act to state and local governments.","sumSrc":"Oyez","by":{"1":"37"}},{"t":"case","label":"Graziadio v. Culinary Inst. of Am.","cite":"817 F.3d 415","y":2016,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/817/415/","by":{"1":"33"}},{"t":"case","label":"Gross v. FBL Fin. Servs., Inc.","cite":"557 U.S. 167","y":2009,"id":"2008/08-441","sc":1,"op":1,"ar":1,"sum":"The Court held that a plaintiff must show that age was the \"but-for\" cause for the defendant's action in an Age Discrimination in Employment Act claim.","sumSrc":"Oyez","by":{"1":"21, 22, 29","2":"6, 13"}},{"t":"case","label":"Haybarger v. Lawrence County Adult Prob. & Parole","cite":"667 F.3d 408","y":2012,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/667/408/","by":{"1":"38"}},{"t":"case","label":"HCSC-Laundry v. United States","cite":"450 U.S. 1","y":1981,"id":"1980/80-338","sc":1,"sum":"A cooperative hospital service organization cannot qualify for exemption from federal income taxation as a charitable organization under § 501 (c)(3) of the Internal Revenue Code of 1954, but instead may qualify only if it performs one of the services listed in § 501 (e) (1) (A). This conclusion is supported both by the principle of statutory construction that a specific statute, here subsection (e), controls over a …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"17"}},{"t":"case","label":"Holloway v. Water Works & Sewer Bd.","cite":"24 F. Supp. 3d 1112","y":2014,"court":"N.D. Ala.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/24/1112/","by":{"1":"5"}},{"t":"case","label":"Jett v. Dall. Indep. Sch. Dist.","cite":"491 U.S. 701","y":1989,"id":"1988/87-2084","sc":1,"sum":"The judgment is affirmed in part, and the cases are remanded. 798 F. 2d 748 and 837 F. 2d 1244, affirmed in part and remanded. JUSTICE O'CONNOR delivered the opinion of the Court with respect to Parts 1, 111, and IV, concluding that:","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"30"}},{"t":"case","label":"Jinks v. Richland County","cite":"538 U.S. 456","y":2003,"id":"2002/02-258","sc":1,"sum":"The Court held that section 1367(d)'s application to claims brought against a State's political subdivisions is constitutional.","sumSrc":"Oyez","by":{"1":"37","2":"27","3":"17, 18"}},{"t":"case","label":"Johnson v. Mayor of Balt.","cite":"472 U.S. 353","y":1985,"id":"1984/84-518","sc":1,"sum":"Title 5 U. S. C. § 8335(b) does not, as a matter of law, establish that age 55 is a BFOQ for nonfederal firefighters within the meaning of the ADEA.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"14","2":"11","3":"10"}},{"t":"case","label":"Liteky v. United States","cite":"510 U.S. 540","y":1994,"id":"1993/92-6921","sc":1,"sum":"Before and during petitioners' 1991 trial on federal criminal charges, the District Judge denied defense motions that he recuse himself pursuant to 28 U. S. C. §455(a), which requires a federal judge to \"disqualify himself in any proceeding in which his impartiality might reasonably be questioned.\" The first motion was based on rulings and statements this same judge made, which allegedly displayed impatience, …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"11"}},{"t":"case","label":"Meyer v. Holley","cite":"537 U.S. 280","y":2003,"id":"2002/01-1120","sc":1,"sum":"The Court held that the FHA imposes liability without fault upon the employer in accordance with traditional agency principles. In other words, the FHA normally imposes vicarious liability upon the corporation, but not upon its officers or owners.","sumSrc":"Oyez","by":{"1":"34","2":"20"}},{"t":"case","label":"Michigan v. Bay Mills Indian Cmty.","cite":"134 S. Ct. 2024","y":2014,"id":"2013/12-515","sc":1,"sum":"The Court held that Indian tribes have sovereign immunity that can only be revoked by Congress, and that the immunity extends to their commercial activities, even if they are not on their protected land.","sumSrc":"Oyez","by":{"1":"31"}},{"t":"case","label":"Milner v. Dep’t of the Navy","cite":"562 U.S. 562","y":2011,"id":"2010/09-1163","sc":1,"sum":"The Court held that documents related to the effect of explosions from Navy exercises did not qualify for withholding under Exception 2 of the Freedom of Information Act.","sumSrc":"Oyez","by":{"1":"24"}},{"t":"case","label":"Modica v. Taylor","cite":"465 F.3d 174","y":2006,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/465/174/","by":{"1":"38"}},{"t":"case","label":"Monroe v. Pape","cite":"365 U.S. 167","y":1961,"id":"1960/39","sc":1,"sum":"Yes and No. Justice William O. Douglas, writing for the majority, stated that the city police officers, in conducting an unreasonable search and seizure, had committed an action which was under the color of law, and that the police could be held liable individually under the Civil Rights Act. However, the majority further held that a municipality could not be liable under the Civil Rights Act.","sumSrc":"Oyez","by":{"1":"18"}},{"t":"case","label":"Morgan v. Safeway Stores, Inc.","cite":"884 F.2d 1211","y":1989,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/884/1211/","by":{"1":"32","3":"13"}},{"t":"case","label":"Murphy v. Smith","cite":"138 S. Ct. 784","y":2018,"id":"2017/16-1067","sc":1,"sum":"A case in which the Court interpreted the parenthetical phrase “not to exceed 25 percent,” as used in 42 U.S.C. § 1997e(d)(2), to mean exactly 25 percent, thereby precluding the district court from exercising its discretion to allocate a lower percentage of the damage award to attorney's fees.","sumSrc":"Oyez","by":{"1":"9"}},{"t":"case","label":"NASA v. FLRA","cite":"527 U.S. 229","y":1999,"id":"1998/98-369","sc":1,"sum":"The Court held that an investigator from NASA's Office of Inspector General is a \"representative\" of NASA when conducting an employee examination covered by the Federal Service Labor-Management Relations Statute, such that the right to union representation in the FSLMRS may be invoked.","sumSrc":"Oyez","by":{"1":"10"}},{"t":"case","label":"Nat’l League of Cities v. Usery","cite":"426 U.S. 833","y":1976,"id":"1974/74-878","sc":1,"sum":"Congress may not regulate the labor market of state employees. The Tenth Amendment prohibits Congress from enacting legislation which operates \"to directly displace the States' freedom to structure integral operations in areas of traditional governmental functions.\" While the power of Congress under the Commerce Clause is \"plenary,\" that power has constitutional limits.","sumSrc":"Oyez","by":{"1":"37, 38","2":"22"}},{"t":"case","label":"NLRB v. SW Gen., Inc.","cite":"137 S. Ct. 929","y":2017,"id":"2016/15-1251","sc":1,"sum":"The Court determined that the limitations on nominees to vacant positions serving in an acting capacity under the Federal Vacancies Reform Act apply equally to first assistants who take on the position and to those who are selected by the President from within the same agency or from another agency.","sumSrc":"Oyez","by":{"1":"24"}},{"t":"case","label":"Nw. Austin Mun. Util. Dist. No. One v. Holder","cite":"557 U.S. 193","y":2009,"id":"2008/08-322","sc":1,"sum":"The Court held that the Voting Rights Act (VRA) permits all political subdivisions to seek bailout from the preclearance requirements of the VRA.","sumSrc":"Oyez","by":{"1":"18"}},{"t":"case","label":"Pers. Adm’r v. Feeney","cite":"442 U.S. 256","y":1979,"id":"1978/78-233","sc":1,"sum":"The Court held that the law was enacted to serve \"legitimate and worthy purposes\" and not to discriminate on the basis of sex. Even though few women benefitted from the scheme, Justice Stewart argued that \"veteran status is not uniquely male.\" Furthermore, the law placed many men who were not veterans at a disadvantage as well.","sumSrc":"Oyez","by":{"1":"31"}},{"t":"case","label":"Pol. Nat’l All. v. NLRB","cite":"322 U.S. 643","y":1944,"id":"scdb/1943-077","sc":1,"sum":"1. In view of the activities of the petitioner in the conduct of its insurance business (described in the opinion), the National Labor Relations Board was justified in concluding that the practices in which the petitioner was found to be and to have been engaged were, within the meaning of the National Labor Relations Act, unfair labor practices \"affecting commerce,\" which the Board was empowered by the Act to …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"38"}},{"t":"case","label":"Price Waterhouse v. Hopkins","cite":"490 U.S. 228","y":1989,"id":"1988/87-1167","sc":1,"sum":"The Supreme Court held that the court of appeals applied the right test, but should have placed the burden at “preponderance of the evidence” not “clear and convincing evidence”. On remand, Price Waterhouse would escape liability if it shows it would have denied Hopkins partnership even if she were not a woman.","sumSrc":"Oyez","by":{"1":"34"}},{"t":"case","label":"Puerto Rico v. Franklin Cal. Tax-Free Tr.","cite":"136 S. Ct. 1938","y":2016,"id":"2015/15-233","sc":1,"sum":"The Court determined that Chapter 9 of the Bankruptcy Code preempted the Puerto Rico statute that allowed public utilities to restructure their debt.","sumSrc":"Oyez","by":{"1":"20"}},{"t":"case","label":"RadLAX Gateway Hotel, LLC v. Amalgamated Bank","cite":"566 U.S. 639","y":2012,"id":"2011/11-166","sc":1,"sum":"The Court held that a company could not obtain confirmation of a Chapter 11 bankruptcy plan that provided for the sale of its assets free from lien without permitting a bank to credit-bid at the sale.","sumSrc":"Oyez","by":{"1":"17","2":"16"}},{"t":"case","label":"Salinas v. United States","cite":"522 U.S. 52","y":1997,"id":"1997/96-738","sc":1,"sum":"The Court held that section 666(a)(1)(B) does not require the Government to prove the bribe in question had a demonstrated effect upon federal funds.","sumSrc":"Oyez","by":{"1":"36"}},{"t":"case","label":"Skidmore v. Swift & Co.","cite":"323 U.S. 134","y":1944,"id":"1940-1955/12","sc":1,"sum":"The Court held that there was no reason that time spent waiting could not also be time spent working, especially in cases in which the conditions of employment involve waiting time. Although it can be difficult to determine the facts of a case and whether the activity in question constitutes work, Congress granted the courts the authority to do so.","sumSrc":"Oyez","by":{"1":"25","2":"30"}},{"t":"case","label":"Spirt v. Teachers Ins. & Annuity Ass’n","cite":"691 F.2d 1054","y":1982,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/691/1054/","ar":1,"by":{"1":"32","2":"19","3":"13"}},{"t":"case","label":"United States v. Lopez","cite":"514 U.S. 549","y":1995,"id":"1994/93-1260","sc":1,"sum":"The Court found the 1990 Gun-Free School Zones Act unconstitutional for overstepping the congressional boundaries of the Commerce Clause.","sumSrc":"Oyez","by":{"1":"37"}},{"t":"case","label":"United States v. Mead Corp.","cite":"533 U.S. 218","y":2001,"id":"2000/99-1434","sc":1,"sum":"The Court held that the \"administrative implementation of a particular statutory provision qualifies for [the greatest level of deference accorded under Chevron U.S.A. Inc. v. Natural Resources Defense Council] when it appears that Congress delegated authority to the agency generally to make rules carrying the force of law, and that the agency interpretation claiming deference was promulgated in the exercise of that authority.\" Justice Souter wrote that \"a tariff classification has no claim to judicial deference under Chevron, there being no indication that Congress intended such a ruling to carry the force of law, but we hold that under Skidmore v. Swift & Co., the ruling is eligible to claim respect according to its persuasiveness.\".","sumSrc":"Oyez","by":{"1":"25"}},{"t":"case","label":"United States v. Menasche","cite":"348 U.S. 528","y":1955,"id":"scdb/1954-050","sc":1,"sum":"An alien who filed his declaration of intention to become an American citizen before the effective date of the Immigration and Nationality Act bf 1952, and who otherwise complied with the naturalization laws then in effect, has a \"status,\" \"condition\" or \"right in process 9 f acquisition\" preserved by § 405 (a), the general savings clause of the 1952 Act, even though his petition for naturalization was filed after …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"19"}},{"t":"case","label":"Univ. of Tex. Sw. Med. Ctr. v. Nassar","cite":"133 S. Ct. 2517","y":2013,"url":"https://www.courtlistener.com/c/S.%20Ct./133/2517/","sc":1,"by":{"1":"21"}},{"t":"case","label":"Weeks v. Maine","cite":"871 F. Supp. 515","y":1994,"court":"D. Me.","url":"https://www.courtlistener.com/c/F.%20Supp./871/515/","by":{"1":"33"}},{"t":"case","label":"Williams v. City of Montgomery","cite":"742 F.2d 586","y":1984,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/742/586/","by":{"1":"32","3":"13"}},{"t":"case","label":"Williams v. Taylor","cite":"529 U.S. 362","y":2000,"id":"1999/98-8384","sc":1,"sum":"In a judgment announced by Justice John Paul Stevens, the Court, with different majorities of Justices for each holding, held that Williams had been deprived of the constitutional right to the effective assistance of counsel and that the Virginia Supreme Court's refusal to set aside the Williams death sentence was a decision that was contrary to or involved an unreasonable application of clearly established federal law, as determined by the Court.","sumSrc":"Oyez","by":{"1":"19"}},{"t":"const","label":"Article I, Section 8, Clause 3","clauses":[["commerce","Commerce Clause"]],"text":"To regulate Commerce with foreign Nations, and among the several States, and with the Indian Tribes;","by":{"1":"9, 37, 38","2":"7, 27, 29"}},{"t":"const","label":"Amendment X","clauses":[["tenth-amendment","Tenth Amendment"]],"text":"The powers not delegated to the United States by the Constitution, nor prohibited by it to the States, are reserved to the States respectively, or to the people.","by":{"1":"37"}},{"t":"const","label":"Amendment XIV","clauses":[["equal-protection","Equal Protection Clause"]],"by":{"1":"30"}},{"t":"law","label":"Pub. L. No. 90-202","url":"https://www.govinfo.gov/link/statute/81/602","by":{"1":"passim"}},{"t":"law","label":"Pub. L. No. 101-336","url":"https://www.govinfo.gov/link/statute/104/327","by":{"1":"8, 26, 28"}},{"t":"law","label":"Pub. L. No. 92-261","url":"https://www.govinfo.gov/link/statute/86/103","by":{"1":"20","2":"6, 12"}},{"t":"law","label":"Pub. L. No. 93-259","url":"https://www.govinfo.gov/link/statute/88/74","by":{"1":"passim","2":"13, 22"}},{"t":"law","label":"Pub. L. No. 103-3","url":"https://www.govinfo.gov/link/statute/107/6","by":{"1":"33, 38"}},{"t":"law","label":"Pub. L. No. 93-112","url":"https://www.govinfo.gov/link/statute/87/355","by":{"1":"14"}},{"t":"usc","label":"7 U.S.C. § 2031","url":"https://www.law.cornell.edu/uscode/text/7/2031","subs":["(j)(3)"],"by":{"1":"12"}},{"t":"usc","label":"12 U.S.C. § 1141j","url":"https://www.law.cornell.edu/uscode/text/12/1141j","subs":["(a)"],"by":{"1":"12"}},{"t":"usc","label":"12 U.S.C. § 1715z-1","url":"https://www.law.cornell.edu/uscode/text/12/1715z-1","subs":["(i)(4)","(s)(2)(D)(iv)"],"by":{"1":"12, 13, 12"}},{"t":"usc","label":"15 U.S.C. § 78c","url":"https://www.law.cornell.edu/uscode/text/15/78c","subs":["(a)(3)(A)"],"by":{"1":"12"}},{"t":"usc","label":"15 U.S.C. § 1471","url":"https://www.law.cornell.edu/uscode/text/15/1471","subs":["(3)"],"by":{"1":"12"}},{"t":"usc","label":"15 U.S.C. § 6809","url":"https://www.law.cornell.edu/uscode/text/15/6809","subs":["(9)"],"by":{"1":"12"}},{"t":"usc","label":"15 U.S.C. § 7006","url":"https://www.law.cornell.edu/uscode/text/15/7006","subs":["(1)"],"by":{"1":"12"}},{"t":"usc","label":"16 U.S.C. § 1532","url":"https://www.law.cornell.edu/uscode/text/16/1532","subs":["(15)"],"by":{"1":"12"}},{"t":"usc","label":"16 U.S.C. § 3371","url":"https://www.law.cornell.edu/uscode/text/16/3371","subs":["(h)","(j)(1)"],"by":{"1":"12, 12"}},{"t":"usc","label":"26 U.S.C. § 170","url":"https://www.law.cornell.edu/uscode/text/26/170","subs":["(c)"],"by":{"1":"12"}},{"t":"usc","label":"26 U.S.C. § 316","url":"https://www.law.cornell.edu/uscode/text/26/316","subs":["(b)(2)(A)","(b)(3)"],"by":{"1":"12, 12"}},{"t":"usc","label":"26 U.S.C. § 401","url":"https://www.law.cornell.edu/uscode/text/26/401","subs":["(c)(3)"],"by":{"1":"12"}},{"t":"usc","label":"26 U.S.C. § 507","url":"https://www.law.cornell.edu/uscode/text/26/507","subs":["(d)(2)(A)"],"by":{"1":"12"}},{"t":"usc","label":"26 U.S.C. § 512","url":"https://www.law.cornell.edu/uscode/text/26/512","subs":["(a)(3)(B)"],"by":{"1":"12"}},{"t":"usc","label":"26 U.S.C. § 581","url":"https://www.law.cornell.edu/uscode/text/26/581","by":{"1":"12"}},{"t":"usc","label":"26 U.S.C. § 1250","url":"https://www.law.cornell.edu/uscode/text/26/1250","subs":["(b)(4)"],"by":{"1":"12"}},{"t":"usc","label":"26 U.S.C. § 4958","url":"https://www.law.cornell.edu/uscode/text/26/4958","subs":["(c)(3)(C)(i)"],"by":{"1":"12"}},{"t":"usc","label":"26 U.S.C. § 7503","url":"https://www.law.cornell.edu/uscode/text/26/7503","by":{"1":"12"}},{"t":"usc","label":"29 U.S.C. § 203","url":"https://www.law.cornell.edu/uscode/text/29/203","subs":["(a)","(d)","(e)","(s)(1)(C)","(s)(1)","(x)"],"stext":{"head":"§203. Definitions","paras":[[0,"As used in this chapter—"],[0,"(a) \"Person\" means an individual, partnership, association, corporation, business trust, legal representative, or any organized group of persons."],[0,"(b) \"Commerce\" means trade, commerce, transportation, transmission, or communication among the several States or between any State and any place outside thereof."],[0,"(c) \"State\" means any State of the United States or the District of Columbia or any Territory or possession of the United States."],[0,"(d) \"Employer\" includes any person acting directly or indirectly in the interest of an employer in relation to an employee and includes a public agency, but does not include any labor organization (other than when acting as an employer) or anyone acting in the capacity of officer or agent of such labor organization."],[0,"(e)(1) Except as provided in paragraphs (2), (3), and (4), the term \"employee\" means any individual employed by an employer."],[0,"(2) In the case of an individual employed by a public agency, such term means—"],[1,"(A) any individual employed by the Government of the United States—"],[2,"(i) as a civilian in the military departments (as defined in section 102 of title 5),"],[2,"(ii) in any executive agency (as defined in section 105 of such title),"],[2,"(iii) in any unit of the judicial branch of the Government which has positions in the competitive service,"],[2,"(iv) in a nonappropriated fund instrumentality under the jurisdiction of the Armed Forces,"],[2,"(v) in the Library of Congress, or"],[2,"(vi) the 1 Government Publishing Office;"],[1,"(B) any individual employed by the United States Postal Service or the Postal Regulatory Commission; and"],[1,"(C) any individual employed by a State, political subdivision of a State, or an interstate governmental agency, other than such an individual—"],[2,"(i) who is not subject to the civil service laws of the State, political subdivision, or agency which employs him; and"],[2,"(ii) who—"],[3,"(I) holds a public elective office of that State, political subdivision, or agency,"],[3,"(II) is selected by the holder of such an office to be a member of his personal staff,"],[3,"(III) is appointed by such an officeholder to serve on a policymaking level,"],[3,"(IV) is an immediate adviser to such an officeholder with respect to the constitutional or legal powers of his office, or"],[3,"(V) is an employee in the legislative branch or legislative body of that State, political subdivision, or agency and is not employed by the legislative library of such State, political subdivision, or agency."],[0,"(3) For purposes of subsection (u), such term does not include any individual employed by an employer engaged in agriculture if such individual is the parent, spouse, child, or other member of the employer's immediate family."],[0,"(4)(A) The term \"employee\" does not include any individual who volunteers to perform services for a public agency which is a State, a political subdivision of a State, or an interstate governmental agency, if—"],[1,"(i) the individual receives no compensation or is paid expenses, reasonable benefits, or a nominal fee to perform the services for which the individual volunteered; and"],[1,"(ii) such services are not the same type of services which the individual is employed to perform for such public agency."],[0,"(B) An employee of a public agency which is a State, political subdivision of a State, or an interstate governmental agency may volunteer to perform services for any other State, political subdivision, or interstate governmental agency, including a State, political subdivision or agency with which the employing State, political subdivision, or agency has a mutual aid agreement."],[0,"(5) The term \"employee\" does not include individuals who volunteer their services solely for humanitarian purposes to private non-profit food banks and who receive from the food banks groceries."],[0,"(f) \"Agriculture\" includes farming in all its branches and among other things includes the cultivation and tillage of the soil, dairying, the production, cultivation, growing, and harvesting of any agricultural or horticultural commodities (including commodities defined as agricultural commodities in section 1141j(g) 2 of title 12), the raising of livestock, bees, fur-bearing animals, or poultry, and any practices (including any forestry or lumbering operations) performed by a farmer or on a farm as an incident to or in conjunction with such farming operations, including preparation for market, delivery to storage or to market or to carriers for transportation to market."],[0,"(g) \"Employ\" includes to suffer or permit to work."],[0,"(h) \"Industry\" means a trade, business, industry, or other activity, or branch or group thereof, in which individuals are gainfully employed."],[0,"(i) \"Goods\" means goods (including ships and marine equipment), wares, products, commodities, merchandise, or articles or subjects of commerce of any character, or any part or ingredient thereof, but does not include goods after their delivery into the actual physical possession of the ultimate consumer thereof other than a producer, manufacturer, or processor thereof."],[0,"(j) \"Produced\" means produced, manufactured, mined, handled, or in any other manner worked on in any State; and for the purposes of this chapter an employee shall be deemed to have been engaged in the production of goods if such employee was employed in producing, manufacturing, mining, handling, transporting, or in any other manner working on such goods, or in any closely related process or occupation directly essential to the production thereof, in any State."],[0,"(k) \"Sale\" or \"sell\" includes any sale, exchange, contract to sell, consignment for sale, shipment for sale, or other disposition."],[0,"(l) \"Oppressive child labor\" means a condition of employment under which (1) any employee under the age of sixteen years is employed by an employer (other than a parent or a person standing in place of a parent employing his own child or a child in his custody under the age of sixteen years in an occupation other than manufacturing or mining or an occupation found by the Secretary of Labor to be particularly hazardous for the employment of children between the ages of sixteen and eighteen years or detrimental to their health or well-being) in any occupation, or (2) any employee between the ages of sixteen and eighteen years is employed by an employer in any occupation which the Secretary of Labor shall find and by order declare to be particularly hazardous for the employment of children between such ages or detrimental to their health or well-being; but oppressive child labor shall not be deemed to exist by virtue of the employment in any occupation of any person with respect to whom the employer shall have on file an unexpired certificate issued and held pursuant to regulations of the Secretary of Labor certifying that such person is above the oppressive child-labor age. The Secretary of Labor shall provide by regulation or by order that the employment of employees between the ages of fourteen and sixteen years in occupations other than manufacturing and mining shall not be deemed to constitute oppressive child labor if and to the extent that the Secretary of Labor determines that such employment is confined to periods which will not interfere with their schooling and to conditions which will not interfere with their health and well-being."],[0,"(m)(1) \"Wage\" paid to any employee includes the reasonable cost, as determined by the Administrator, to the employer of furnishing such employee with board, lodging, or other facilities, if such board, lodging or other facilities are customarily furnished by such employer to his employees: Provided, That the cost of board, lodging, or other facilities shall not be included as a part of the wage paid to any employee to the extent it is excluded therefrom under the terms of a bona fide collective-bargaining agreement applicable to the particular employee: Provided further, That the Secretary is authorized to determine the fair value of such board, lodging, or other facilities for defined classes of employees and in defined areas, based on average cost to the employer or to groups of employers similarly situated, or average value to groups of employees, or other appropriate measures of fair value. Such evaluations, where applicable and pertinent, shall be used in lieu of actual measure of cost in determining the wage paid to any employee."],[0,"(2)(A) In determining the wage an employer is required to pay a tipped employee, the amount paid such employee by the employee's employer shall be an amount equal to—"],[1,"(i) the cash wage paid such employee which for purposes of such determination shall be not less than the cash wage required to be paid such an employee on August 20, 1996; and"],[1,"(ii) an additional amount on account of the tips received by such employee which amount is equal to the difference between the wage specified in clause (i) and the wage in effect under section 206(a)(1) of this title."],[0,"The additional amount on account of tips may not exceed the value of the tips actually received by an employee. The preceding 2 sentences shall not apply with respect to any tipped employee unless such employee has been informed by the employer of the provisions of this subsection, and all tips received by such employee have been retained by the employee, except that this subsection shall not be construed to prohibit the pooling of tips among employees who customarily and regularly receive tips."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/203?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§203. Definitions","tname":"Labor","by":{"1":"28, 23, 27, 28, 38, 23, 27, 38, 38","2":"28, 28, 28"}},{"t":"usc","label":"29 U.S.C. § 207","url":"https://www.law.cornell.edu/uscode/text/29/207","by":{"1":"23"}},{"t":"usc","label":"29 U.S.C. § 213","url":"https://www.law.cornell.edu/uscode/text/29/213","subs":["(b)(20)"],"by":{"1":"23"}},{"t":"usc","label":"29 U.S.C. § 216","url":"https://www.law.cornell.edu/uscode/text/29/216","stext":{"head":"§216. Penalties","paras":[[0,"(a) Fines and imprisonment"],[0,"Any person who willfully violates any of the provisions of section 215 of this title shall upon conviction thereof be subject to a fine of not more than $10,000, or to imprisonment for not more than six months, or both. No person shall be imprisoned under this subsection except for an offense committed after the conviction of such person for a prior offense under this subsection."],[0,"(b) Damages; right of action; attorney's fees and costs; termination of right of action"],[0,"Any employer who violates the provisions of section 206 or section 207 of this title shall be liable to the employee or employees affected in the amount of their unpaid minimum wages, or their unpaid overtime compensation, as the case may be, and in an additional equal amount as liquidated damages. Any employer who violates the provisions of section 215(a)(3) or 218d of this title shall be liable for such legal or equitable relief as may be appropriate to effectuate the purposes of section 215(a)(3) or 218d of this title, including without limitation employment, reinstatement, promotion, and the payment of wages lost and an additional equal amount as liquidated damages. Any employer who violates section 203(m)(2)(B) of this title shall be liable to the employee or employees affected in the amount of the sum of any tip credit taken by the employer and all such tips unlawfully kept by the employer, and in an additional equal amount as liquidated damages. An action to recover the liability prescribed in the preceding sentences may be maintained against any employer (including a public agency) in any Federal or State court of competent jurisdiction by any one or more employees for and in behalf of himself or themselves and other employees similarly situated. No employee shall be a party plaintiff to any such action unless he gives his consent in writing to become such a party and such consent is filed in the court in which such action is brought. The court in such action shall, in addition to any judgment awarded to the plaintiff or plaintiffs, allow a reasonable attorney's fee to be paid by the defendant, and costs of the action. The right provided by this subsection to bring an action by or on behalf of any employee, and the right of any employee to become a party plaintiff to any such action, shall terminate upon the filing of a complaint by the Secretary of Labor in an action under section 217 of this title in which (1) restraint is sought of any further delay in the payment of unpaid minimum wages, or the amount of unpaid overtime compensation, as the case may be, owing to such employee under section 206 or section 207 of this title by an employer liable therefor under the provisions of this subsection or (2) legal or equitable relief is sought as a result of alleged violations of section 215(a)(3) or 218d of this title."],[0,"(c) Payment of wages and compensation; waiver of claims; actions by the Secretary; limitation of actions"],[0,"The Secretary is authorized to supervise the payment of the unpaid minimum wages or the unpaid overtime compensation owing to any employee or employees under section 206 or section 207 of this title, and the agreement of any employee to accept such payment shall upon payment in full constitute a waiver by such employee of any right he may have under subsection (b) of this section to such unpaid minimum wages or unpaid overtime compensation and an additional equal amount as liquidated damages. The Secretary may bring an action in any court of competent jurisdiction to recover the amount of unpaid minimum wages or overtime compensation and an equal amount as liquidated damages. The right provided by subsection (b) to bring an action by or on behalf of any employee to recover the liability specified in the first sentence of such subsection and of any employee to become a party plaintiff to any such action shall terminate upon the filing of a complaint by the Secretary in an action under this subsection in which a recovery is sought of unpaid minimum wages or unpaid overtime compensation under sections 206 and 207 of this title or liquidated or other damages provided by this subsection owing to such employee by an employer liable under the provisions of subsection (b), unless such action is dismissed without prejudice on motion of the Secretary. Any sums thus recovered by the Secretary of Labor on behalf of an employee pursuant to this subsection shall be held in a special deposit account and shall be paid, on order of the Secretary of Labor, directly to the employee or employees affected. Any such sums not paid to an employee because of inability to do so within a period of three years shall be covered into the Treasury of the United States as miscellaneous receipts. In determining when an action is commenced by the Secretary of Labor under this subsection for the purposes of the statutes of limitations provided in section 6(a) of the Portal-to-Portal Act of 1947 [29 U.S.C. 255(a)], it shall be considered to be commenced in the case of any individual claimant on the date when the complaint is filed if he is specifically named as a party plaintiff in the complaint, or if his name did not so appear, on the subsequent date on which his name is added as a party plaintiff in such action. The authority and requirements described in this subsection shall apply with respect to a violation of section 203(m)(2)(B) of this title, as appropriate, and the employer shall be liable for the amount of the sum of any tip credit taken by the employer and all such tips unlawfully kept by the employer, and an additional equal amount as liquidated damages."],[0,"(d) Savings provisions"],[0,"In any action or proceeding commenced prior to, on, or after August 8, 1956, no employer shall be subject to any liability or punishment under this chapter or the Portal-to-Portal Act of 1947 [29 U.S.C. 251 et seq.] on account of his failure to comply with any provision or provisions of this chapter or such Act (1) with respect to work heretofore or hereafter performed in a workplace to which the exemption in section 213(f) of this title is applicable, (2) with respect to work performed in Guam, the Canal Zone or Wake Island before the effective date of this amendment of subsection (d), or (3) with respect to work performed in a possession named in section 206(a)(3) 1 of this title at any time prior to the establishment by the Secretary, as provided therein, of a minimum wage rate applicable to such work."],[0,"(e) Civil penalties for certain violations"],[0,"(1)(A) Any person who violates the provisions of sections 2 212 or 213(c) of this title, relating to child labor, or any regulation issued pursuant to such sections, shall be subject to a civil penalty not to exceed—"],[1,"(i) $11,000 for each employee who was the subject of such a violation; or"],[1,"(ii) $50,000 with regard to each such violation that causes the death or serious injury of any employee under the age of 18 years, which penalty may be doubled where the violation is a repeated or willful violation."],[0,"(B) For purposes of subparagraph (A), the term \"serious injury\" means—"],[1,"(i) permanent loss or substantial impairment of one of the senses (sight, hearing, taste, smell, tactile sensation);"],[1,"(ii) permanent loss or substantial impairment of the function of a bodily member, organ, or mental faculty, including the loss of all or part of an arm, leg, foot, hand or other body part; or"],[1,"(iii) permanent paralysis or substantial impairment that causes loss of movement or mobility of an arm, leg, foot, hand or other body part."],[0,"(2) Any person who repeatedly or willfully violates section 206 or 207 of this title, relating to wages, shall be subject to a civil penalty not to exceed $1,100 for each such violation. Any person who violates section 203(m)(2)(B) of this title shall be subject to a civil penalty not to exceed $1,100 for each such violation, as the Secretary determines appropriate, in addition to being liable to the employee or employees affected for all tips unlawfully kept, and an additional equal amount as liquidated damages, as described in subsection (b)."],[0,"(3) In determining the amount of any penalty under this subsection, the appropriateness of such penalty to the size of the business of the person charged and the gravity of the violation shall be considered. The amount of any penalty under this subsection, when finally determined, may be—"],[1,"(A) deducted from any sums owing by the United States to the person charged;"],[1,"(B) recovered in a civil action brought by the Secretary in any court of competent jurisdiction, in which litigation the Secretary shall be represented by the Solicitor of Labor; or"],[1,"(C) ordered by the court, in an action brought for a violation of section 215(a)(4) of this title or a repeated or willful violation of section 215(a)(2) of this title, to be paid to the Secretary."],[0,"(4) Any administrative determination by the Secretary of the amount of any penalty under this subsection shall be final, unless within 15 days after receipt of notice thereof by certified mail the person charged with the violation takes exception to the determination that the violations for which the penalty is imposed occurred, in which event final determination of the penalty shall be made in an administrative proceeding after opportunity for hearing in accordance with section 554 of title 5 and regulations to be promulgated by the Secretary."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/216?type=usc&year=mostrecent&link-type=html"},"head":"§216. Penalties","tname":"Labor","by":{"1":"33","2":"22"}},{"t":"usc","label":"29 U.S.C. § 623","url":"https://www.law.cornell.edu/uscode/text/29/623","subs":["(a)","(a)(1)","(b)","(d)"],"stext":{"head":"§623. Prohibition of age discrimination","paras":[[0,"(a) Employer practices"],[0,"It shall be unlawful for an employer—"],[1,"(1) to fail or refuse to hire or to discharge any individual or otherwise discriminate against any individual with respect to his compensation, terms, conditions, or privileges of employment, because of such individual's age;"],[1,"(2) to limit, segregate, or classify his employees in any way which would deprive or tend to deprive any individual of employment opportunities or otherwise adversely affect his status as an employee, because of such individual's age; or"],[1,"(3) to reduce the wage rate of any employee in order to comply with this chapter."],[0,"(b) Employment agency practices"],[0,"It shall be unlawful for an employment agency to fail or refuse to refer for employment, or otherwise to discriminate against, any individual because of such individual's age, or to classify or refer for employment any individual on the basis of such individual's age."],[0,"(c) Labor organization practices"],[0,"It shall be unlawful for a labor organization—"],[1,"(1) to exclude or to expel from its membership, or otherwise to discriminate against, any individual because of his age;"],[1,"(2) to limit, segregate, or classify its membership, or to classify or fail or refuse to refer for employment any individual, in any way which would deprive or tend to deprive any individual of employment opportunities, or would limit such employment opportunities or otherwise adversely affect his status as an employee or as an applicant for employment, because of such individual's age;"],[1,"(3) to cause or attempt to cause an employer to discriminate against an individual in violation of this section."],[0,"(d) Opposition to unlawful practices; participation in investigations, proceedings, or litigation"],[0,"It shall be unlawful for an employer to discriminate against any of his employees or applicants for employment, for an employment agency to discriminate against any individual, or for a labor organization to discriminate against any member thereof or applicant for membership, because such individual, member or applicant for membership has opposed any practice made unlawful by this section, or because such individual, member or applicant for membership has made a charge, testified, assisted, or participated in any manner in an investigation, proceeding, or litigation under this chapter."],[0,"(e) Printing or publication of notice or advertisement indicating preference, limitation, etc."],[0,"It shall be unlawful for an employer, labor organization, or employment agency to print or publish, or cause to be printed or published, any notice or advertisement relating to employment by such an employer or membership in or any classification or referral for employment by such a labor organization, or relating to any classification or referral for employment by such an employment agency, indicating any preference, limitation, specification, or discrimination, based on age."],[0,"(f) Lawful practices; age an occupational qualification; other reasonable factors; laws of foreign workplace; seniority system; employee benefit plans; discharge or discipline for good cause"],[0,"It shall not be unlawful for an employer, employment agency, or labor organization—"],[1,"(1) to take any action otherwise prohibited under subsections (a), (b), (c), or (e) of this section where age is a bona fide occupational qualification reasonably necessary to the normal operation of the particular business, or where the differentiation is based on reasonable factors other than age, or where such practices involve an employee in a workplace in a foreign country, and compliance with such subsections would cause such employer, or a corporation controlled by such employer, to violate the laws of the country in which such workplace is located;"],[1,"(2) to take any action otherwise prohibited under subsection (a), (b), (c), or (e) of this section—"],[2,"(A) to observe the terms of a bona fide seniority system that is not intended to evade the purposes of this chapter, except that no such seniority system shall require or permit the involuntary retirement of any individual specified by section 631(a) of this title because of the age of such individual; or"],[2,"(B) to observe the terms of a bona fide employee benefit plan—"],[3,"(i) where, for each benefit or benefit package, the actual amount of payment made or cost incurred on behalf of an older worker is no less than that made or incurred on behalf of a younger worker, as permissible under section 1625.10, title 29, Code of Federal Regulations (as in effect on June 22, 1989); or"],[3,"(ii) that is a voluntary early retirement incentive plan consistent with the relevant purpose or purposes of this chapter."],[1,"Notwithstanding clause (i) or (ii) of subparagraph (B), no such employee benefit plan or voluntary early retirement incentive plan shall excuse the failure to hire any individual, and no such employee benefit plan shall require or permit the involuntary retirement of any individual specified by section 631(a) of this title, because of the age of such individual. An employer, employment agency, or labor organization acting under subparagraph (A), or under clause (i) or (ii) of subparagraph (B), shall have the burden of proving that such actions are lawful in any civil enforcement proceeding brought under this chapter; or"],[1,"(3) to discharge or otherwise discipline an individual for good cause."],[0,"(g) Repealed. Pub. L. 101–239, title VI, §6202(b)(3)(C)(i), Dec. 19, 1989, 103 Stat. 2233"],[0,"(h) Practices of foreign corporations controlled by American employers; foreign employers not controlled by American employers; factors determining control"],[0,"(1) If an employer controls a corporation whose place of incorporation is in a foreign country, any practice by such corporation prohibited under this section shall be presumed to be such practice by such employer."],[0,"(2) The prohibitions of this section shall not apply where the employer is a foreign person not controlled by an American employer."],[0,"(3) For the purpose of this subsection the determination of whether an employer controls a corporation shall be based upon the—"],[1,"(A) interrelation of operations,"],[1,"(B) common management,"],[1,"(C) centralized control of labor relations, and"],[1,"(D) common ownership or financial control,"],[0,"of the employer and the corporation."],[0,"(i) Employee pension benefit plans; cessation or reduction of benefit accrual or of allocation to employee account; distribution of benefits after attainment of normal retirement age; compliance; highly compensated employees"],[0,"(1) Except as otherwise provided in this subsection, it shall be unlawful for an employer, an employment agency, a labor organization, or any combination thereof to establish or maintain an employee pension benefit plan which requires or permits—"],[1,"(A) in the case of a defined benefit plan, the cessation of an employee's benefit accrual, or the reduction of the rate of an employee's benefit accrual, because of age, or"],[1,"(B) in the case of a defined contribution plan, the cessation of allocations to an employee's account, or the reduction of the rate at which amounts are allocated to an employee's account, because of age."],[0,"(2) Nothing in this section shall be construed to prohibit an employer, employment agency, or labor organization from observing any provision of an employee pension benefit plan to the extent that such provision imposes (without regard to age) a limitation on the amount of benefits that the plan provides or a limitation on the number of years of service or years of participation which are taken into account for purposes of determining benefit accrual under the plan."],[0,"(3) In the case of any employee who, as of the end of any plan year under a defined benefit plan, has attained normal retirement age under such plan—"],[1,"(A) if distribution of benefits under such plan with respect to such employee has commenced as of the end of such plan year, then any requirement of this subsection for continued accrual of benefits under such plan with respect to such employee during such plan year shall be treated as satisfied to the extent of the actuarial equivalent of in-service distribution of benefits, and"],[1,"(B) if distribution of benefits under such plan with respect to such employee has not commenced as of the end of such year in accordance with section 1056(a)(3) of this title and section 401(a)(14)(C) of title 26, and the payment of benefits under such plan with respect to such employee is not suspended during such plan year pursuant to section 1053(a)(3)(B) of this title or section 411(a)(3)(B) of title 26, then any requirement of this subsection for continued accrual of benefits under such plan with respect to such employee during such plan year shall be treated as satisfied to the extent of any adjustment in the benefit payable under the plan during such plan year attributable to the delay in the distribution of benefits after the attainment of normal retirement age."],[0,"The provisions of this paragraph shall apply in accordance with regulations of the Secretary of the Treasury. Such regulations shall provide for the application of the preceding provisions of this paragraph to all employee pension benefit plans subject to this subsection and may provide for the application of such provisions, in the case of any such employee, with respect to any period of time within a plan year."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/623?type=usc&year=mostrecent&link-type=html"},"head":"§623. Prohibition of age discrimination","tname":"Labor","by":{"1":"1","2":"33, 33, 33, 33, 33"}},{"t":"usc","label":"29 U.S.C. § 626","url":"https://www.law.cornell.edu/uscode/text/29/626","subs":["(b)","(a)"],"stext":{"head":"§626. Recordkeeping, investigation, and enforcement","paras":[[0,"(a) Attendance of witnesses; investigations, inspections, records, and homework regulations"],[0,"The Equal Employment Opportunity Commission shall have the power to make investigations and require the keeping of records necessary or appropriate for the administration of this chapter in accordance with the powers and procedures provided in sections 209 and 211 of this title."],[0,"(b) Enforcement; prohibition of age discrimination under fair labor standards; unpaid minimum wages and unpaid overtime compensation; liquidated damages; judicial relief; conciliation, conference, and persuasion"],[0,"The provisions of this chapter shall be enforced in accordance with the powers, remedies, and procedures provided in sections 211(b), 216 (except for subsection (a) thereof), and 217 of this title, and subsection (c) of this section. Any act prohibited under section 623 of this title shall be deemed to be a prohibited act under section 215 of this title. Amounts owing to a person as a result of a violation of this chapter shall be deemed to be unpaid minimum wages or unpaid overtime compensation for purposes of sections 216 and 217 of this title: Provided, That liquidated damages shall be payable only in cases of willful violations of this chapter. In any action brought to enforce this chapter the court shall have jurisdiction to grant such legal or equitable relief as may be appropriate to effectuate the purposes of this chapter, including without limitation judgments compelling employment, reinstatement or promotion, or enforcing the liability for amounts deemed to be unpaid minimum wages or unpaid overtime compensation under this section. Before instituting any action under this section, the Equal Employment Opportunity Commission shall attempt to eliminate the discriminatory practice or practices alleged, and to effect voluntary compliance with the requirements of this chapter through informal methods of conciliation, conference, and persuasion."],[0,"(c) Civil actions; persons aggrieved; jurisdiction; judicial relief; termination of individual action upon commencement of action by Commission; jury trial"],[0,"(1) Any person aggrieved may bring a civil action in any court of competent jurisdiction for such legal or equitable relief as will effectuate the purposes of this chapter: Provided, That the right of any person to bring such action shall terminate upon the commencement of an action by the Equal Employment Opportunity Commission to enforce the right of such employee under this chapter."],[0,"(2) In an action brought under paragraph (1), a person shall be entitled to a trial by jury of any issue of fact in any such action for recovery of amounts owing as a result of a violation of this chapter, regardless of whether equitable relief is sought by any party in such action."],[0,"(d) Filing of charge with Commission; timeliness; conciliation, conference, and persuasion; unlawful practice"],[0,"(1) No civil action may be commenced by an individual under this section until 60 days after a charge alleging unlawful discrimination has been filed with the Equal Employment Opportunity Commission. Such a charge shall be filed—"],[1,"(A) within 180 days after the alleged unlawful practice occurred; or"],[1,"(B) in a case to which section 633(b) of this title applies, within 300 days after the alleged unlawful practice occurred, or within 30 days after receipt by the individual of notice of termination of proceedings under State law, whichever is earlier."],[0,"(2) Upon receiving such a charge, the Commission shall promptly notify all persons named in such charge as prospective defendants in the action and shall promptly seek to eliminate any alleged unlawful practice by informal methods of conciliation, conference, and persuasion."],[0,"(3) For purposes of this section, an unlawful practice occurs, with respect to discrimination in compensation in violation of this chapter, when a discriminatory compensation decision or other practice is adopted, when a person becomes subject to a discriminatory compensation decision or other practice, or when a person is affected by application of a discriminatory compensation decision or other practice, including each time wages, benefits, or other compensation is paid, resulting in whole or in part from such a decision or other practice."],[0,"(e) Reliance on administrative rulings; notice of dismissal or termination; civil action after receipt of notice"],[0,"Section 259 of this title shall apply to actions under this chapter. If a charge filed with the Commission under this chapter is dismissed or the proceedings of the Commission are otherwise terminated by the Commission, the Commission shall notify the person aggrieved. A civil action may be brought under this section by a person defined in section 630(a) of this title against the respondent named in the charge within 90 days after the date of the receipt of such notice."],[0,"(f) Waiver"],[0,"(1) An individual may not waive any right or claim under this chapter unless the waiver is knowing and voluntary. Except as provided in paragraph (2), a waiver may not be considered knowing and voluntary unless at a minimum—"],[1,"(A) the waiver is part of an agreement between the individual and the employer that is written in a manner calculated to be understood by such individual, or by the average individual eligible to participate;"],[1,"(B) the waiver specifically refers to rights or claims arising under this chapter;"],[1,"(C) the individual does not waive rights or claims that may arise after the date the waiver is executed;"],[1,"(D) the individual waives rights or claims only in exchange for consideration in addition to anything of value to which the individual already is entitled;"],[1,"(E) the individual is advised in writing to consult with an attorney prior to executing the agreement;"],[1,"(F)(i) the individual is given a period of at least 21 days within which to consider the agreement; or"],[1,"(ii) if a waiver is requested in connection with an exit incentive or other employment termination program offered to a group or class of employees, the individual is given a period of at least 45 days within which to consider the agreement;"],[1,"(G) the agreement provides that for a period of at least 7 days following the execution of such agreement, the individual may revoke the agreement, and the agreement shall not become effective or enforceable until the revocation period has expired;"],[1,"(H) if a waiver is requested in connection with an exit incentive or other employment termination program offered to a group or class of employees, the employer (at the commencement of the period specified in subparagraph (F)) informs the individual in writing in a manner calculated to be understood by the average individual eligible to participate, as to—"],[2,"(i) any class, unit, or group of individuals covered by such program, any eligibility factors for such program, and any time limits applicable to such program; and"],[2,"(ii) the job titles and ages of all individuals eligible or selected for the program, and the ages of all individuals in the same job classification or organizational unit who are not eligible or selected for the program."],[0,"(2) A waiver in settlement of a charge filed with the Equal Employment Opportunity Commission, or an action filed in court by the individual or the individual's representative, alleging age discrimination of a kind prohibited under section 623 or 633a of this title may not be considered knowing and voluntary unless at a minimum—"],[1,"(A) subparagraphs (A) through (E) of paragraph (1) have been met; and"],[1,"(B) the individual is given a reasonable period of time within which to consider the settlement agreement."],[0,"(3) In any dispute that may arise over whether any of the requirements, conditions, and circumstances set forth in subparagraph (A), (B), (C), (D), (E), (F), (G), or (H) of paragraph (1), or subparagraph (A) or (B) of paragraph (2), have been met, the party asserting the validity of a waiver shall have the burden of proving in a court of competent jurisdiction that a waiver was knowing and voluntary pursuant to paragraph (1) or (2)."],[0,"(4) No waiver agreement may affect the Commission's rights and responsibilities to enforce this chapter. No waiver may be used to justify interfering with the protected right of an employee to file a charge or participate in an investigation or proceeding conducted by the Commission."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/626?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§626. Recordkeeping, investigation, and enforcement","tname":"Labor","by":{"1":"1, 27","2":"1, 22"}},{"t":"usc","label":"29 U.S.C. § 628","url":"https://www.law.cornell.edu/uscode/text/29/628","by":{"1":"2"}},{"t":"usc","label":"29 U.S.C. § 630","url":"https://www.law.cornell.edu/uscode/text/29/630","subs":["(a)","(b)","(b)(1970)","(c)"],"stext":{"head":"§630. Definitions","paras":[[0,"For the purposes of this chapter—"],[0,"(a) The term \"person\" means one or more individuals, partnerships, associations, labor organizations, corporations, business trusts, legal representatives, or any organized groups of persons."],[0,"(b) The term \"employer\" means a person engaged in an industry affecting commerce who has twenty or more employees for each working day in each of twenty or more calendar weeks in the current or preceding calendar year: Provided, That prior to June 30, 1968, employers having fewer than fifty employees shall not be considered employers. The term also means (1) any agent of such a person, and (2) a State or political subdivision of a State and any agency or instrumentality of a State or a political subdivision of a State, and any interstate agency, but such term does not include the United States, or a corporation wholly owned by the Government of the United States."],[0,"(c) The term \"employment agency\" means any person regularly undertaking with or without compensation to procure employees for an employer and includes an agent of such a person; but shall not include an agency of the United States."],[0,"(d) The term \"labor organization\" means a labor organization engaged in an industry affecting commerce, and any agent of such an organization, and includes any organization of any kind, any agency, or employee representation committee, group, association, or plan so engaged in which employees participate and which exists for the purpose, in whole or in part, of dealing with employers concerning grievances, labor disputes, wages, rates of pay, hours, or other terms or conditions of employment, and any conference, general committee, joint or system board, or joint council so engaged which is subordinate to a national or international labor organization."],[0,"(e) A labor organization shall be deemed to be engaged in an industry affecting commerce if (1) it maintains or operates a hiring hall or hiring office which procures employees for an employer or procures for employees opportunities to work for an employer, or (2) the number of its members (or, where it is a labor organization composed of other labor organizations or their representatives, if the aggregate number of the members of such other labor organization) is fifty or more prior to July 1, 1968, or twenty-five or more on or after July 1, 1968, and such labor organization—"],[1,"(1) is the certified representative of employees under the provisions of the National Labor Relations Act, as amended [29 U.S.C. 151 et seq.], or the Railway Labor Act, as amended [45 U.S.C. 151 et seq.]; or"],[1,"(2) although not certified, is a national or international labor organization or a local labor organization recognized or acting as the representative of employees of an employer or employers engaged in an industry affecting commerce; or"],[1,"(3) has chartered a local labor organization or subsidiary body which is representing or actively seeking to represent employees of employers within the meaning of paragraph (1) or (2); or"],[1,"(4) has been chartered by a labor organization representing or actively seeking to represent employees within the meaning of paragraph (1) or (2) as the local or subordinate body through which such employees may enjoy membership or become affiliated with such labor organization; or"],[1,"(5) is a conference, general committee, joint or system board, or joint council subordinate to a national or international labor organization, which includes a labor organization engaged in an industry affecting commerce within the meaning of any of the preceding paragraphs of this subsection."],[0,"(f) The term \"employee\" means an individual employed by any employer except that the term \"employee\" shall not include any person elected to public office in any State or political subdivision of any State by the qualified voters thereof, or any person chosen by such officer to be on such officer's personal staff, or an appointee on the policymaking level or an immediate adviser with respect to the exercise of the constitutional or legal powers of the office. The exemption set forth in the preceding sentence shall not include employees subject to the civil service laws of a State government, governmental agency, or political subdivision. The term \"employee\" includes any individual who is a citizen of the United States employed by an employer in a workplace in a foreign country."],[0,"(g) The term \"commerce\" means trade, traffic, commerce, transportation, transmission, or communication among the several States; or between a State and any place outside thereof; or within the District of Columbia, or a possession of the United States; or between points in the same State but through a point outside thereof."],[0,"(h) The term \"industry affecting commerce\" means any activity, business, or industry in commerce or in which a labor dispute would hinder or obstruct commerce or the free flow of commerce and includes any activity or industry \"affecting commerce\" within the meaning of the Labor-Management Reporting and Disclosure Act of 1959 [29 U.S.C. 401 et seq.]."],[0,"(i) The term \"State\" includes a State of the United States, the District of Columbia, Puerto Rico, the Virgin Islands, American Samoa, Guam, Wake Island, the Canal Zone, and Outer Continental Shelf lands defined in the Outer Continental Shelf Lands Act [43 U.S.C. 1331 et seq.]."],[0,"(j) The term \"firefighter\" means an employee, the duties of whose position are primarily to perform work directly connected with the control and extinguishment of fires or the maintenance and use of firefighting apparatus and equipment, including an employee engaged in this activity who is transferred to a supervisory or administrative position."],[0,"(k) The term \"law enforcement officer\" means an employee, the duties of whose position are primarily the investigation, apprehension, or detention of individuals suspected or convicted of offenses against the criminal laws of a State, including an employee engaged in this activity who is transferred to a supervisory or administrative position. For the purpose of this subsection, \"detention\" includes the duties of employees assigned to guard individuals incarcerated in any penal institution."],[0,"(l) The term \"compensation, terms, conditions, or privileges of employment\" encompasses all employee benefits, including such benefits provided pursuant to a bona fide employee benefit plan."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/630?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§630. Definitions","tname":"Labor","by":{"1":"2, 14, 15, 28, passim, passim","2":"2, 2, 2, 19, 19, 19"}},{"t":"usc","label":"29 U.S.C. § 633a","url":"https://www.law.cornell.edu/uscode/text/29/633a","subs":["(a)"],"stext":{"head":"§633a. Nondiscrimination on account of age in Federal Government employment","paras":[[0,"(a) Federal agencies affected"],[0,"All personnel actions affecting employees or applicants for employment who are at least 40 years of age (except personnel actions with regard to aliens employed outside the limits of the United States) in military departments as defined in section 102 of title 5, in executive agencies as defined in section 105 of title 5 (including employees and applicants for employment who are paid from nonappropriated funds), in the United States Postal Service and the Postal Regulatory Commission, in those units in the government of the District of Columbia having positions in the competitive service, and in those units of the judicial branch of the Federal Government having positions in the competitive service, in the Smithsonian Institution, and in the Government Publishing Office, the Government Accountability Office, and the Library of Congress shall be made free from any discrimination based on age."],[0,"(b) Enforcement by Equal Employment Opportunity Commission and by Librarian of Congress in the Library of Congress; remedies; rules, regulations, orders, and instructions of Commission: compliance by Federal agencies; powers and duties of Commission; notification of final action on complaint of discrimination; exemptions: bona fide occupational qualification"],[0,"Except as otherwise provided in this subsection, the Equal Employment Opportunity Commission is authorized to enforce the provisions of subsection (a) through appropriate remedies, including reinstatement or hiring of employees with or without backpay, as will effectuate the policies of this section. The Equal Employment Opportunity Commission shall issue such rules, regulations, orders, and instructions as it deems necessary and appropriate to carry out its responsibilities under this section. The Equal Employment Opportunity Commission shall—"],[1,"(1) be responsible for the review and evaluation of the operation of all agency programs designed to carry out the policy of this section, periodically obtaining and publishing (on at least a semiannual basis) progress reports from each department, agency, or unit referred to in subsection (a);"],[1,"(2) consult with and solicit the recommendations of interested individuals, groups, and organizations relating to nondiscrimination in employment on account of age; and"],[1,"(3) provide for the acceptance and processing of complaints of discrimination in Federal employment on account of age."],[0,"The head of each such department, agency, or unit shall comply with such rules, regulations, orders, and instructions of the Equal Employment Opportunity Commission which shall include a provision that an employee or applicant for employment shall be notified of any final action taken on any complaint of discrimination filed by him thereunder. Reasonable exemptions to the provisions of this section may be established by the Commission but only when the Commission has established a maximum age requirement on the basis of a determination that age is a bona fide occupational qualification necessary to the performance of the duties of the position. With respect to employment in the Library of Congress, authorities granted in this subsection to the Equal Employment Opportunity Commission shall be exercised by the Librarian of Congress."],[0,"(c) Civil actions; jurisdiction; relief"],[0,"Any person aggrieved may bring a civil action in any Federal district court of competent jurisdiction for such legal or equitable relief as will effectuate the purposes of this chapter."],[0,"(d) Notice to Commission; time of notice; Commission notification of prospective defendants; Commission elimination of unlawful practices"],[0,"When the individual has not filed a complaint concerning age discrimination with the Commission, no civil action may be commenced by any individual under this section until the individual has given the Commission not less than thirty days' notice of an intent to file such action. Such notice shall be filed within one hundred and eighty days after the alleged unlawful practice occurred. Upon receiving a notice of intent to sue, the Commission shall promptly notify all persons named therein as prospective defendants in the action and take any appropriate action to assure the elimination of any unlawful practice."],[0,"(e) Duty of Government agency or official"],[0,"Nothing contained in this section shall relieve any Government agency or official of the responsibility to assure nondiscrimination on account of age in employment as required under any provision of Federal law."],[0,"(f) Applicability of statutory provisions to personnel action of Federal departments, etc."],[0,"Any personnel action of any department, agency, or other entity referred to in subsection (a) of this section shall not be subject to, or affected by, any provision of this chapter, other than the provisions of sections 626(d)(3) and 631(b) of this title and the provisions of this section."],[0,"(g) Study and report to President and Congress by Equal Employment Opportunity Commission; scope"],[0,"(1) The Equal Employment Opportunity Commission shall undertake a study relating to the effects of the amendments made to this section by the Age Discrimination in Employment Act Amendments of 1978, and the effects of section 631(b) of this title."],[0,"(2) The Equal Employment Opportunity Commission shall transmit a report to the President and to the Congress containing the findings of the Commission resulting from the study of the Commission under paragraph (1) of this subsection. Such report shall be transmitted no later than January 1, 1980."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/633a?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§633a. Nondiscrimination on account of age in Federal Government employment","tname":"Labor","by":{"1":"2, 14, 20, 28","2":"19"}},{"t":"usc","label":"29 U.S.C. § 2611","url":"https://www.law.cornell.edu/uscode/text/29/2611","subs":["(4)(A)(i)","(4)(B)","(4)(A)"],"stext":{"head":"§2611. Definitions","paras":[[0,"As used in this subchapter:"],[0,"(1) Commerce"],[1,"The terms \"commerce\" and \"industry or activity affecting commerce\" mean any activity, business, or industry in commerce or in which a labor dispute would hinder or obstruct commerce or the free flow of commerce, and include \"commerce\" and any \"industry affecting commerce\", as defined in paragraphs (1) and (3) of section 142 of this title."],[0,"(2) Eligible employee"],[0,"(A) In general"],[2,"The term \"eligible employee\" means an employee who has been employed—"],[3,"(i) for at least 12 months by the employer with respect to whom leave is requested under section 2612 of this title; and"],[3,"(ii) for at least 1,250 hours of service with such employer during the previous 12-month period."],[0,"(B) Exclusions"],[2,"The term \"eligible employee\" does not include—"],[3,"(i) any Federal officer or employee covered under subchapter V of chapter 63 of title 5; or"],[3,"(ii) any employee of an employer who is employed at a worksite at which such employer employs less than 50 employees if the total number of employees employed by that employer within 75 miles of that worksite is less than 50."],[0,"(C) Determination"],[2,"For purposes of determining whether an employee meets the hours of service requirement specified in subparagraph (A)(ii), the legal standards established under section 207 of this title shall apply."],[0,"(D) Airline flight crews"],[0,"(i) Determination"],[3,"For purposes of determining whether an employee who is a flight attendant or flight crewmember (as such terms are defined in regulations of the Federal Aviation Administration) meets the hours of service requirement specified in subparagraph (A)(ii), the employee will be considered to meet the requirement if—"],[4,"(I) the employee has worked or been paid for not less than 60 percent of the applicable total monthly guarantee, or the equivalent, for the previous 12-month period, for or by the employer with respect to whom leave is requested under section 2612 of this title; and"],[4,"(II) the employee has worked or been paid for not less than 504 hours (not counting personal commute time or time spent on vacation leave or medical or sick leave) during the previous 12-month period, for or by that employer."],[0,"(ii) File"],[3,"Each employer of an employee described in clause (i) shall maintain on file with the Secretary (in accordance with such regulations as the Secretary may prescribe) containing information specifying the applicable monthly guarantee with respect to each category of employee to which such guarantee applies."],[0,"(iii) Definition"],[3,"In this subparagraph, the term \"applicable monthly guarantee\" means—"],[4,"(I) for an employee described in clause (i) other than an employee on reserve status, the minimum number of hours for which an employer has agreed to schedule such employee for any given month; and"],[4,"(II) for an employee described in clause (i) who is on reserve status, the number of hours for which an employer has agreed to pay such employee on reserve status for any given month,"],[0,"as established in the applicable collective bargaining agreement or, if none exists, in the employer's policies."],[0,"(E) GAO employees"],[2,"In the case of an employee of the Government Accountability Office, the requirements of subparagraph (A) shall not apply with respect to leave under section 2612(a)(1)(A) or (B) of this title."],[0,"(3) Employ; employee; State"],[1,"The terms \"employ\", \"employee\", and \"State\" have the same meanings given such terms in subsections (c), (e), and (g) of section 203 of this title."],[0,"(4) Employer"],[0,"(A) In general"],[2,"The term \"employer\"—"],[3,"(i) means any person engaged in commerce or in any industry or activity affecting commerce who employs 50 or more employees for each working day during each of 20 or more calendar workweeks in the current or preceding calendar year;"],[3,"(ii) includes—"],[4,"(I) any person who acts, directly or indirectly, in the interest of an employer to any of the employees of such employer; and"],[4,"(II) any successor in interest of an employer;"],[3,"(iii) includes any \"public agency\", as defined in section 203(x) of this title; and"],[3,"(iv) includes the Government Accountability Office and the Library of Congress."],[0,"(B) Public agency"],[2,"For purposes of subparagraph (A)(iii), a public agency shall be considered to be a person engaged in commerce or in an industry or activity affecting commerce."],[0,"(5) Employment benefits"],[1,"The term \"employment benefits\" means all benefits provided or made available to employees by an employer, including group life insurance, health insurance, disability insurance, sick leave, annual leave, educational benefits, and pensions, regardless of whether such benefits are provided by a practice or written policy of an employer or through an \"employee benefit plan\", as defined in section 1002(3) of this title."],[0,"(6) Health care provider"],[1,"The term \"health care provider\" means—"],[2,"(A) a doctor of medicine or osteopathy who is authorized to practice medicine or surgery (as appropriate) by the State in which the doctor practices; or"],[2,"(B) any other person determined by the Secretary to be capable of providing health care services."],[0,"(7) Parent"],[1,"The term \"parent\" means the biological parent of an employee or an individual who stood in loco parentis to an employee when the employee was a son or daughter."],[0,"(8) Person"],[1,"The term \"person\" has the same meaning given such term in section 203(a) of this title."],[0,"(9) Reduced leave schedule"],[1,"The term \"reduced leave schedule\" means a leave schedule that reduces the usual number of hours per workweek, or hours per workday, of an employee."],[0,"(10) Secretary"],[1,"The term \"Secretary\" means the Secretary of Labor."],[0,"(11) Serious health condition"],[1,"The term \"serious health condition\" means an illness, injury, impairment, or physical or mental condition that involves—"],[2,"(A) inpatient care in a hospital, hospice, or residential medical care facility; or"],[2,"(B) continuing treatment by a health care provider."],[0,"(12) Son or daughter"],[1,"The term \"son or daughter\" means a biological, adopted, or foster child, a stepchild, a legal ward, or a child of a person standing in loco parentis, who is—"],[2,"(A) under 18 years of age; or"],[2,"(B) 18 years of age or older and incapable of self-care because of a mental or physical disability."],[0,"(13) Spouse"],[1,"The term \"spouse\" means a husband or wife, as the case may be."],[0,"(14) Covered active duty"],[1,"The term \"covered active duty\" means—"],[2,"(A) in the case of a member of a regular component of the Armed Forces, duty during the deployment of the member with the Armed Forces to a foreign country; and"],[2,"(B) in the case of a member of a reserve component of the Armed Forces, duty during the deployment of the member with the Armed Forces to a foreign country under a call or order to active duty under a provision of law referred to in section 101(a)(13)(B) of title 10."],[0,"(15) Covered servicemember"],[1,"The term \"covered servicemember\" means—"],[2,"(A) a member of the Armed Forces (including a member of the National Guard or Reserves) who is undergoing medical treatment, recuperation, or therapy, is otherwise in outpatient status, or is otherwise on the temporary disability retired list, for a serious injury or illness; or"],[2,"(B) a veteran who is undergoing medical treatment, recuperation, or therapy, for a serious injury or illness and who was a member of the Armed Forces (including a member of the National Guard or Reserves) at any time during the period of 5 years preceding the date on which the veteran undergoes that medical treatment, recuperation, or therapy."],[0,"(16) Outpatient status"],[1,"The term \"outpatient status\", with respect to a covered servicemember, means the status of a member of the Armed Forces assigned to—"],[2,"(A) a military medical treatment facility as an outpatient; or"],[2,"(B) a unit established for the purpose of providing command and control of members of the Armed Forces receiving medical care as outpatients."],[0,"(17) Next of kin"],[1,"The term \"next of kin\", used with respect to an individual, means the nearest blood relative of that individual."],[0,"(18) Serious injury or illness"],[1,"The term \"serious injury or illness\"—"],[2,"(A) in the case of a member of the Armed Forces (including a member of the National Guard or Reserves), means an injury or illness that was incurred by the member in line of duty on active duty in the Armed Forces (or existed before the beginning of the member's active duty and was aggravated by service in line of duty on active duty in the Armed Forces) and that may render the member medically unfit to perform the duties of the member's office, grade, rank, or rating; and"],[2,"(B) in the case of a veteran who was a member of the Armed Forces (including a member of the National Guard or Reserves) at any time during a period described in paragraph (15)(B), means a qualifying (as defined by the Secretary of Labor) injury or illness that was incurred by the member in line of duty on active duty in the Armed Forces (or existed before the beginning of the member's active duty and was aggravated by service in line of duty on active duty in the Armed Forces) and that manifested itself before or after the member became a veteran."],[0,"(19) Veteran"],[1,"The term \"veteran\" has the meaning given the term in section 101 of title 38."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/2611?type=usc&year=mostrecent&link-type=html"},"head":"§2611. Definitions","tname":"Labor","by":{"1":"38, 38","2":"28, 28"}},{"t":"usc","label":"31 U.S.C. § 6501","url":"https://www.law.cornell.edu/uscode/text/31/6501","subs":["(4)(B)"],"by":{"1":"12"}},{"t":"usc","label":"38 U.S.C. § 3452","url":"https://www.law.cornell.edu/uscode/text/38/3452","subs":["(b)"],"by":{"1":"12"}},{"t":"usc","label":"42 U.S.C. § 1437a","url":"https://www.law.cornell.edu/uscode/text/42/1437a","subs":["(c)(2)"],"by":{"1":"12"}},{"t":"usc","label":"42 U.S.C. § 1471","url":"https://www.law.cornell.edu/uscode/text/42/1471","subs":["(b)(3)"],"by":{"1":"12"}},{"t":"usc","label":"42 U.S.C. § 1485","url":"https://www.law.cornell.edu/uscode/text/42/1485","subs":["(e)(1)"],"by":{"1":"12"}},{"t":"usc","label":"42 U.S.C. § 6372","url":"https://www.law.cornell.edu/uscode/text/42/6372","subs":["(2)"],"by":{"1":"12"}},{"t":"usc","label":"42 U.S.C. § 8259","url":"https://www.law.cornell.edu/uscode/text/42/8259","subs":["(6)"],"by":{"1":"12"}},{"t":"usc","label":"42 U.S.C. § 1981","url":"https://www.law.cornell.edu/uscode/text/42/1981","by":{"1":"30"}},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","by":{"1":"18, 30, 35"}},{"t":"usc","label":"42 U.S.C. § 2000e-2","url":"https://www.law.cornell.edu/uscode/text/42/2000e-2","subs":["(m)"],"by":{"1":"21"}},{"t":"usc","label":"42 U.S.C. § 2000e","url":"https://www.law.cornell.edu/uscode/text/42/2000e","subs":["(a)","(b)","(h)"],"stext":{"head":"§2000e. Definitions","paras":[[0,"For the purposes of this subchapter—"],[1,"(a) The term \"person\" includes one or more individuals, governments, governmental agencies, political subdivisions, labor unions, partnerships, associations, corporations, legal representatives, mutual companies, joint-stock companies, trusts, unincorporated organizations, trustees, trustees in cases under title 11, or receivers."],[1,"(b) The term \"employer\" means a person engaged in an industry affecting commerce who has fifteen or more employees for each working day in each of twenty or more calendar weeks in the current or preceding calendar year, and any agent of such a person, but such term does not include (1) the United States, a corporation wholly owned by the Government of the United States, an Indian tribe, or any department or agency of the District of Columbia subject by statute to procedures of the competitive service (as defined in section 2102 of title 5), or (2) a bona fide private membership club (other than a labor organization) which is exempt from taxation under section 501(c) of title 26, except that during the first year after March 24, 1972, persons having fewer than twenty-five employees (and their agents) shall not be considered employers."],[1,"(c) The term \"employment agency\" means any person regularly undertaking with or without compensation to procure employees for an employer or to procure for employees opportunities to work for an employer and includes an agent of such a person."],[1,"(d) The term \"labor organization\" means a labor organization engaged in an industry affecting commerce, and any agent of such an organization, and includes any organization of any kind, any agency, or employee representation committee, group, association, or plan so engaged in which employees participate and which exists for the purpose, in whole or in part, of dealing with employers concerning grievances, labor disputes, wages, rates of pay, hours, or other terms or conditions of employment, and any conference, general committee, joint or system board, or joint council so engaged which is subordinate to a national or international labor organization."],[1,"(e) A labor organization shall be deemed to be engaged in an industry affecting commerce if (1) it maintains or operates a hiring hall or hiring office which procures employees for an employer or procures for employees opportunities to work for an employer, or (2) the number of its members (or, where it is a labor organization composed of other labor organizations or their representatives, if the aggregate number of the members of such other labor organization) is (A) twenty-five or more during the first year after March 24, 1972, or (B) fifteen or more thereafter, and such labor organization—"],[2,"(1) is the certified representative of employees under the provisions of the National Labor Relations Act, as amended [29 U.S.C. 151 et seq.], or the Railway Labor Act, as amended [45 U.S.C. 151 et seq.];"],[2,"(2) although not certified, is a national or international labor organization or a local labor organization recognized or acting as the representative of employees of an employer or employers engaged in an industry affecting commerce; or"],[2,"(3) has chartered a local labor organization or subsidiary body which is representing or actively seeking to represent employees of employers within the meaning of paragraph (1) or (2); or"],[2,"(4) has been chartered by a labor organization representing or actively seeking to represent employees within the meaning of paragraph (1) or (2) as the local or subordinate body through which such employees may enjoy membership or become affiliated with such labor organization; or"],[2,"(5) is a conference, general committee, joint or system board, or joint council subordinate to a national or international labor organization, which includes a labor organization engaged in an industry affecting commerce within the meaning of any of the preceding paragraphs of this subsection."],[1,"(f) The term \"employee\" means an individual employed by an employer, except that the term \"employee\" shall not include any person elected to public office in any State or political subdivision of any State by the qualified voters thereof, or any person chosen by such officer to be on such officer's personal staff, or an appointee on the policy making level or an immediate adviser with respect to the exercise of the constitutional or legal powers of the office. The exemption set forth in the preceding sentence shall not include employees subject to the civil service laws of a State government, governmental agency or political subdivision. With respect to employment in a foreign country, such term includes an individual who is a citizen of the United States."],[1,"(g) The term \"commerce\" means trade, traffic, commerce, transportation, transmission, or communication among the several States; or between a State and any place outside thereof; or within the District of Columbia, or a possession of the United States; or between points in the same State but through a point outside thereof."],[1,"(h) The term \"industry affecting commerce\" means any activity, business, or industry in commerce or in which a labor dispute would hinder or obstruct commerce or the free flow of commerce and includes any activity or industry \"affecting commerce\" within the meaning of the Labor-Management Reporting and Disclosure Act of 1959 [29 U.S.C. 401 et seq.], and further includes any governmental industry, business, or activity."],[1,"(i) The term \"State\" includes a State of the United States, the District of Columbia, Puerto Rico, the Virgin Islands, American Samoa, Guam, Wake Island, the Canal Zone, and Outer Continental Shelf lands defined in the Outer Continental Shelf Lands Act [43 U.S.C. 1331 et seq.]."],[1,"(j) The term \"religion\" includes all aspects of religious observance and practice, as well as belief, unless an employer demonstrates that he is unable to reasonably accommodate to an employee's or prospective employee's religious observance or practice without undue hardship on the conduct of the employer's business."],[1,"(k) The terms \"because of sex\" or \"on the basis of sex\" include, but are not limited to, because of or on the basis of pregnancy, childbirth, or related medical conditions; and women affected by pregnancy, childbirth, or related medical conditions shall be treated the same for all employment-related purposes, including receipt of benefits under fringe benefit programs, as other persons not so affected but similar in their ability or inability to work, and nothing in section 2000e–2(h) of this title shall be interpreted to permit otherwise. This subsection shall not require an employer to pay for health insurance benefits for abortion, except where the life of the mother would be endangered if the fetus were carried to term, or except where medical complications have arisen from an abortion: Provided, That nothing herein shall preclude an employer from providing abortion benefits or otherwise affect bargaining agreements in regard to abortion."],[1,"(l) The term \"complaining party\" means the Commission, the Attorney General, or a person who may bring an action or proceeding under this subchapter."],[1,"(m) The term \"demonstrates\" means meets the burdens of production and persuasion."],[1,"(n) The term \"respondent\" means an employer, employment agency, labor organization, joint labor-management committee controlling apprenticeship or other training or retraining program, including an on-the-job training program, or Federal entity subject to section 2000e–16 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000e?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§2000e. Definitions","tname":"The Public Health and Welfare","by":{"1":"20, 20","2":"4, 28, 28, 28, 28"}},{"t":"usc","label":"46 U.S.C. § 31301","url":"https://www.law.cornell.edu/uscode/text/46/31301","subs":["(6)(B)"],"by":{"1":"12"}},{"t":"case","label":"(III) Cases—Continued: Bond v. United States","cite":"134 S. Ct. 2077","y":2014,"url":"https://www.courtlistener.com/c/S.%20Ct./134/2077/","sc":1,"by":{"2":"26"}},{"t":"case","label":"Burgess v. United States","cite":"553 U.S. 124","y":2008,"id":"2007/06-11429","sc":1,"sum":"The Court upheld the sentencing hike, stating that the definition of a felony drug offense in 12 U.S.C. 841 as punishable by imprisonment for more than one year was controlling regardless of whether South Carolina classified the offense as a felony or a misdemeanor.","sumSrc":"Oyez","by":{"2":"10"}},{"t":"case","label":"Burlington N. & Santa Fe Ry. Co. v. United States","cite":"556 U.S. 599","y":2009,"id":"2008/07-1601","sc":1,"sum":"The Court found that the defendants were not liable as the \"arranger\" for the contamination at issue, and therefore the liability calculations of the district court were appropriate.","sumSrc":"Oyez","by":{"2":"21"}},{"t":"case","label":"Carcieri v. Salazar","cite":"555 U.S. 379","y":2009,"id":"2008/07-526","sc":1,"sum":"The Court found that only tribes under federal jurisdiction at the time of the Indian Reorganization Act of 1934 are subject to taking by the federal government.","sumSrc":"Oyez","by":{"2":"8"}},{"t":"case","label":"Carparts Distribution Ctr., Inc. v. Automotive Wholesaler’s Ass’n of New England, Inc.","cite":"37 F.3d 12","y":1994,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/37/12/","by":{"2":"19"}},{"t":"case","label":"Christopher v. SmithKline Beecham Corp.","cite":"567 U.S. 142","y":2012,"id":"2011/11-204","sc":1,"sum":"The Court held that the Secretary of Labor's definition of \"outside salesman\" apply to pharmaceutical sales representatives under the Fair Labor Standards Act.","sumSrc":"Oyez","by":{"2":"10"}},{"t":"case","label":"Circuit City Stores, Inc. v. Adams","cite":"532 U.S. 105","y":2001,"id":"2000/99-1379","sc":1,"op":3,"ar":2,"sum":"The Court held that section 1 exemption is confined to transportation workers. \"The wording of [section 1] calls for the application of the maxim ejusdem generis, the statutory canon that 'where general words follow specific words in a statutory enumeration, the general words are construed to embrace only objects similar in nature to those objects enumerated by the preceding specific words,'\" wrote Justice Kennedy.","sumSrc":"Oyez","by":{"2":"16"}},{"t":"case","label":"Corning Glass Works v. Brennan","cite":"417 U.S. 188","y":1974,"id":"1973/73-29","sc":1,"sum":"Male employees at the Corning Glass Works (Corning) previously performed night shift inspection and were paid more than females, who performed the day shift inspection. A plantwide shift differential that subsequently came with unionization was superimposed on the existing base-wage difference between male night inspectors and female day inspectors. Thereafter, beginning June 1, 1966, Coming began to open up night …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"22"}},{"t":"case","label":"Crawford v. Metropolitan Gov’t of Nashville & Davidson Cnty.","cite":"555 U.S. 271","y":2009,"id":"2008/06-1595","sc":1,"sum":"The Court held that the anti-retaliation provision of Title VII extends to people who participate in an internal investigation, even if they are not speaking on their own initiative.","sumSrc":"Oyez","by":{"2":"9"}},{"t":"case","label":"EEOC v. Hudson Twp.","cite":"1986 WL 6479","y":1986,"court":"N.D. Ohio Mar. 13","by":{"2":"29"}},{"t":"case","label":"EEOC v. Washington Suburban Sanitary Comm’n","cite":"631 F.3d 174","y":2011,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/631/174/","by":{"2":"27"}},{"t":"case","label":"Gonzales v. Raich","cite":"545 U.S. 1","y":2005,"id":"2004/03-1454","sc":1,"sum":"The Court ruled that the commerce clause of the Controlled Substances Act gives Congress authority to prohibit the local cultivation and use of marijuana, despite state law to the contrary.","sumSrc":"Oyez","by":{"2":"29"}},{"t":"case","label":"Jennings v. Rodriguez","cite":"138 S. Ct. 830","y":2018,"id":"2017/15-1204","sc":1,"sum":"The Court held that non-citizens who are subject to mandatory detention under the Immigration and Nationality Act are not entitled to periodic bond hearings. with the possibility of release if they are detained for longer than six months.","sumSrc":"Oyez","by":{"2":"27, 28"}},{"t":"case","label":"Kasten v. Saint-Gobain Performance Plastics Corp.","cite":"563 U.S. 1","y":2011,"id":"2010/09-834","sc":1,"sum":"The Court held that the Fair Labor Standards Act applies to a complaint, whether oral or written.","sumSrc":"Oyez","by":{"2":"30"}},{"t":"case","label":"Lewis v. City of Chi.","cite":"560 U.S. 205","y":2010,"id":"2009/08-974","sc":1,"sum":"The Court held that an employee may file a Title VII disparate impact claim within 300 days after their employer executes the allegedly unlawful practice.","sumSrc":"Oyez","by":{"2":"29"}},{"t":"case","label":"Leykis v. NYP Holdings, Inc.","cite":"899 F. Supp. 986","y":1995,"court":"E.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./899/986/","sum":"Concluding that, because Section 630(b) “d[oes] not specifically state that an agent would be independently and individually liable,” it authorizes suits against individuals only in their “official capacities for the purposes of respondeat superior liability”.","sumSrc":"brief:2","by":{"2":"21"}},{"t":"case","label":"Microsoft Corp. v. i4i Ltd. P’ship","cite":"564 U.S. 91","y":2011,"id":"2010/10-290","sc":1,"sum":"The Court held that a challenge to a patent's validity must offer clear and convincing evidence.","sumSrc":"Oyez","by":{"2":"18"}},{"t":"case","label":"Nebraska v. Parker","cite":"136 S. Ct. 1072","y":2016,"id":"2015/14-1406","sc":1,"sum":"The Court determined that the passage of the 1882 Act by Congress did not diminish the original boundaries of the Omaha Indian Reservation.","sumSrc":"Oyez","by":{"2":"5, 8"}},{"t":"case","label":"Parker v. Macon Cty. Soil & Water Conservation Dist.","cite":"2010 WL 105721","y":2010,"court":"C.D. Ill. Jan. 5","sum":"Finding genuine issue of material fact whether small water district was part of state agriculture department.","sumSrc":"brief:2","by":{"2":"33"}},{"t":"case","label":"Pennsylvania Dep’t of Corr. v. Yeskey","cite":"524 U.S. 206","y":1998,"id":"1997/97-634","sc":1,"sum":"The Court held that under the ADA no \"public entity\" may discriminate against qualified disabled individuals due to their disability. Moreover, the Court stated that the ADA's protections extended to cover prison inmates as well as any other liberated citizen.","sumSrc":"Oyez","by":{"2":"26"}},{"t":"case","label":"Seminole Tribe of Fla. v. Florida","cite":"517 U.S. 44","y":1996,"id":"1995/94-12","sc":1,"sum":"In a 5-to-4 decision, The Court held that Congress did intend to abrogate states' sovereign immunity under the IGRA but that the Indian Commerce Clause (and by implication the Commerce Clause) did not give Congress that power. Under the Eleventh Amendment, all states are regarded as sovereign entities.","sumSrc":"Oyez","by":{"2":"27"}},{"t":"case","label":"United States v. Gonzales","cite":"520 U.S. 1","y":1997,"id":"1996/95-1605","sc":1,"sum":"In a 7-to-2 decision delivered by Justice Sandra Day O'Connor, the Court announced \"[t]he plain language of (the law) forbids a district court to direct that a term of imprisonment under the statute run concurrently with any other term of imprisonment, whether state or federal.\".","sumSrc":"Oyez","by":{"2":"21"}},{"t":"case","label":"United States v. Texas","cite":"507 U.S. 529","y":1993,"id":"1992/91-1729","sc":1,"sum":"The Act left in place the States' federal common-law obligation to pay prejudgment interest on debts owed to the Federal Government.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"20"}},{"t":"case","label":"Vermont Agency of Natural Res. v. United States ex rel. Stevens","cite":"529 U.S. 765","y":2000,"id":"1999/98-1828","sc":1,"sum":"The Court held that a private individual has standing to bring suit in federal court on behalf of the United States under the False Claims Act, but that the False Claims Act does not subject a state or state agency to liability in such actions. The Court concluded that the False Claims Act does not include states as \"persons\" who can be sued under the law.","sumSrc":"Oyez","by":{"2":"16","3":"7, 8"}},{"t":"case","label":"Wisconsin Cent. Ltd. v. United States","cite":"138 S. Ct. 2067","y":2018,"id":"2017/17-530","sc":1,"sum":"The Court decided that employee stock options are not taxable “compensation” under the Railroad Retirement Tax Act because they are not “money remuneration.”","sumSrc":"Oyez","by":{"2":"13"}},{"t":"usc","label":"29 U.S.C. § 621","url":"https://www.law.cornell.edu/uscode/text/29/621","subs":["(b)"],"stext":{"head":"§621. Congressional statement of findings and purpose","paras":[[0,"(a) The Congress hereby finds and declares that—"],[1,"(1) in the face of rising productivity and affluence, older workers find themselves disadvantaged in their efforts to retain employment, and especially to regain employment when displaced from jobs;"],[1,"(2) the setting of arbitrary age limits regardless of potential for job performance has become a common practice, and certain otherwise desirable practices may work to the disadvantage of older persons;"],[1,"(3) the incidence of unemployment, especially long-term unemployment with resultant deterioration of skill, morale, and employer acceptability is, relative to the younger ages, high among older workers; their numbers are great and growing; and their employment problems grave;"],[1,"(4) the existence in industries affecting commerce, of arbitrary discrimination in employment because of age, burdens commerce and the free flow of goods in commerce."],[0,"(b) It is therefore the purpose of this chapter to promote employment of older persons based on their ability rather than age; to prohibit arbitrary age discrimination in employment; to help employers and workers find ways of meeting problems arising from the impact of age on employment."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/621?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§621. Congressional statement of findings and purpose","tname":"Labor","by":{"2":"1, 2"}},{"t":"usc","label":"42 U.S.C. § 12101","url":"https://www.law.cornell.edu/uscode/text/42/12101","by":{"2":"19"}},{"t":"usc","label":"42 U.S.C. § 12111","url":"https://www.law.cornell.edu/uscode/text/42/12111","subs":["(5)","(7)"],"stext":{"head":"§12111. Definitions","paras":[[0,"As used in this subchapter:"],[0,"(1) Commission"],[1,"The term \"Commission\" means the Equal Employment Opportunity Commission established by section 2000e–4 of this title."],[0,"(2) Covered entity"],[1,"The term \"covered entity\" means an employer, employment agency, labor organization, or joint labor-management committee."],[0,"(3) Direct threat"],[1,"The term \"direct threat\" means a significant risk to the health or safety of others that cannot be eliminated by reasonable accommodation."],[0,"(4) Employee"],[1,"The term \"employee\" means an individual employed by an employer. With respect to employment in a foreign country, such term includes an individual who is a citizen of the United States."],[0,"(5) Employer"],[0,"(A) In general"],[2,"The term \"employer\" means a person engaged in an industry affecting commerce who has 15 or more employees for each working day in each of 20 or more calendar weeks in the current or preceding calendar year, and any agent of such person, except that, for two years following the effective date of this subchapter, an employer means a person engaged in an industry affecting commerce who has 25 or more employees for each working day in each of 20 or more calendar weeks in the current or preceding year, and any agent of such person."],[0,"(B) Exceptions"],[2,"The term \"employer\" does not include—"],[3,"(i) the United States, a corporation wholly owned by the government of the United States, or an Indian tribe; or"],[3,"(ii) a bona fide private membership club (other than a labor organization) that is exempt from taxation under section 501(c) of title 26."],[0,"(6) Illegal use of drugs"],[0,"(A) In general"],[2,"The term \"illegal use of drugs\" means the use of drugs, the possession or distribution of which is unlawful under the Controlled Substances Act [21 U.S.C. 801 et seq.]. Such term does not include the use of a drug taken under supervision by a licensed health care professional, or other uses authorized by the Controlled Substances Act or other provisions of Federal law."],[0,"(B) Drugs"],[2,"The term \"drug\" means a controlled substance, as defined in schedules I through V of section 202 of the Controlled Substances Act [21 U.S.C. 812]."],[0,"(7) Person, etc."],[1,"The terms \"person\", \"labor organization\", \"employment agency\", \"commerce\", and \"industry affecting commerce\", shall have the same meaning given such terms in section 2000e of this title."],[0,"(8) Qualified individual"],[1,"The term \"qualified individual\" means an individual who, with or without reasonable accommodation, can perform the essential functions of the employment position that such individual holds or desires. For the purposes of this subchapter, consideration shall be given to the employer's judgment as to what functions of a job are essential, and if an employer has prepared a written description before advertising or interviewing applicants for the job, this description shall be considered evidence of the essential functions of the job."],[0,"(9) Reasonable accommodation"],[1,"The term \"reasonable accommodation\" may include—"],[2,"(A) making existing facilities used by employees readily accessible to and usable by individuals with disabilities; and"],[2,"(B) job restructuring, part-time or modified work schedules, reassignment to a vacant position, acquisition or modification of equipment or devices, appropriate adjustment or modifications of examinations, training materials or policies, the provision of qualified readers or interpreters, and other similar accommodations for individuals with disabilities."],[0,"(10) Undue hardship"],[0,"(A) In general"],[2,"The term \"undue hardship\" means an action requiring significant difficulty or expense, when considered in light of the factors set forth in subparagraph (B)."],[0,"(B) Factors to be considered"],[2,"In determining whether an accommodation would impose an undue hardship on a covered entity, factors to be considered include—"],[3,"(i) the nature and cost of the accommodation needed under this chapter;"],[3,"(ii) the overall financial resources of the facility or facilities involved in the provision of the reasonable accommodation; the number of persons employed at such facility; the effect on expenses and resources, or the impact otherwise of such accommodation upon the operation of the facility;"],[3,"(iii) the overall financial resources of the covered entity; the overall size of the business of a covered entity with respect to the number of its employees; the number, type, and location of its facilities; and"],[3,"(iv) the type of operation or operations of the covered entity, including the composition, structure, and functions of the workforce of such entity; the geographic separateness, administrative, or fiscal relationship of the facility or facilities in question to the covered entity."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/12111?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§12111. Definitions","tname":"The Public Health and Welfare","by":{"2":"28, 28"}},{"t":"law","label":"Pub. L. No. 88-38","url":"https://www.govinfo.gov/link/statute/77/56","by":{"2":"22"}},{"t":"usc","label":"29 U.S.C. § 201","url":"https://www.law.cornell.edu/uscode/text/29/201","by":{"2":"6"}},{"t":"usc","label":"29 U.S.C. § 211","url":"https://www.law.cornell.edu/uscode/text/29/211","subs":["(b)"],"by":{"2":"22"}},{"t":"usc","label":"29 U.S.C. § 217","url":"https://www.law.cornell.edu/uscode/text/29/217","by":{"2":"22"}},{"t":"usc","label":"29 U.S.C. § 2601","url":"https://www.law.cornell.edu/uscode/text/29/2601","by":{"2":"28"}},{"t":"usc","label":"18 U.S.C. § 229F","url":"https://www.law.cornell.edu/uscode/text/18/229F","subs":["(6)(A)"],"by":{"2":"10"}},{"t":"usc","label":"26 U.S.C. § 3231","url":"https://www.law.cornell.edu/uscode/text/26/3231","subs":["(b)"],"by":{"2":"10"}},{"t":"usc","label":"42 U.S.C. § 10101","url":"https://www.law.cornell.edu/uscode/text/42/10101","subs":["(18)"],"by":{"2":"10"}},{"t":"reg","label":"3 C.F.R. pt. 404","url":"https://www.ecfr.gov/current/title-3/part-404","by":{"2":"22"}},{"t":"reg","label":"3 C.F.R. pt. 321","url":"https://www.ecfr.gov/current/title-3/part-321","by":{"2":"22"}},{"t":"reg","label":"29 C.F.R. § 1625.31","url":"https://www.ecfr.gov/current/title-29/section-1625.31","by":{"2":"33"}},{"t":"case","label":"Burlington Indus., Inc. v. Ellerth","cite":"524 U.S. 742","y":1998,"id":"1997/97-569","sc":1,"sum":"In a 7-to-2 opinion, the Court held that employers are vicariously liable for supervisors who create hostile working conditions for those over whom they have authority.","sumSrc":"Oyez","by":{"3":"11, 13, 15, 23"}},{"t":"case","label":"FDA v. Brown & Williamson Tobacco Corp.","cite":"529 U.S. 120","y":2000,"id":"1999/98-1152","sc":1,"sum":"The Court held that \"Congress has not given the FDA the authority to regulate tobacco products as customarily marketed.\" The ruling was based on the FDCA as a whole and in conjunction with Congress' subsequent tobacco-specific legislation. \"By no means do we question the seriousness of the problem that the FDA has sought to address,\" Justice O'Connor wrote for the majority.","sumSrc":"Oyez","by":{"3":"3"}},{"t":"case","label":"Georgia v. Evans","cite":"316 U.S. 159","y":1942,"id":"scdb/1941-097","sc":1,"sum":"A State is a \"person\" within the meaning of § 7 of the Sherman Act and entitled thereby to sue for treble damages when, as a purchaser of asphalt, it is injured by a combination suppressing competition and fixing prices of that commodity in interstate commerce. United States v. Cooper Corp., 312 U. S. 600, distinguished. P. 162. 123 F. 2d 57, reversed. Courts of other states have considered similar questions. Henry …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"8"}},{"t":"case","label":"Graham Cty. Soil & Water Conservation Dist. v. United States ex rel. Wilson","cite":"559 U.S. 280","y":2010,"id":"2009/08-304","sc":1,"sum":"The Court held that an audit performed by a state or its political subdivisions constitutes an administrative report within the False Claims Act.","sumSrc":"Oyez","by":{"3":"4"}},{"t":"case","label":"Quern v. Mandley","cite":"436 U.S. 725","y":1978,"id":"1977/76-1159","sc":1,"sum":"This litigation originated as a challenge to the validity of Illinois' Emergency Assistance to Needy Families with Children (EA) program under Title IV-A of the Social Security Act (SSA). The Court of Appeals, reversing the District Court, first held that the program was invalid because it limited eligibility for such assistance more narrowly than § 406 (e) (1) of the SSA, which makes federal matching funds …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"4"}},{"t":"case","label":"Raygor v. Regents of Univ. of Minn.","cite":"534 U.S. 533","y":2002,"id":"2001/00-1514","sc":1,"sum":"The Court held that the Board of Regents of the University of Minnesota never consented to suit in federal court on Raygor and Goodrich's state law claims and that the federal supplemental jurisdiction statute does not toll the period of limitations for state law claims asserted against nonconsenting state defendants that are dismissed on Eleventh Amendment grounds.","sumSrc":"Oyez","by":{"3":"18"}},{"t":"case","label":"Wooten v. McDonald Transit Assocs., Inc.","cite":"788 F.3d 490","y":2015,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/788/490/","by":{"3":"25"}}]};